insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (43, 3, 1, 9, 'سورة آل عمران ١ – ٩', 'إنزال الكتاب، والمحكم والمتشابه', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 43) = $j$[{"lbl": "الآيات ١ – ٦", "q": "الٓمٓ ﴿١﴾ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُ ﴿٢﴾ نَزَّلَ عَلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَأَنزَلَ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ ﴿٣﴾ مِن قَبۡلُ هُدٗى لِّلنَّاسِ وَأَنزَلَ ٱلۡفُرۡقَانَۗ إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدٞۗ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ ﴿٤﴾ إِنَّ ٱللَّهَ لَا يَخۡفَىٰ عَلَيۡهِ شَيۡءٞ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ ﴿٥﴾ هُوَ ٱلَّذِي يُصَوِّرُكُمۡ فِي ٱلۡأَرۡحَامِ كَيۡفَ يَشَآءُۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٦﴾", "w": [["الله", "المعبود بحق."], ["لا إله إلا هو", "لا معبود بحق سواه."], ["الحيّ", "ذو الحياة المستلزمة للإرادة والعلم والسمع والبصر والقدرة."], ["القيّوم", "القائم على كل مخلوقاته بالتربية والرعاية والحفظ."], ["الكتاب", "القرآن."], ["بالحق", "متلبّساً به؛ إذ كل ما فيه حق وصدق لا باطل فيه بوجه من الوجوه."], ["مصدقاً لما بين يديه", "من الكتب السابقة، لا يخالفها ولا يبطلها؛ لأن مصدر الجميع واحد هو الله."], ["التوراة", "كتاب موسى ﵇، ومعناها بالعبرية: الشريعة."], ["الإنجيل", "كتاب عيسى ﵇، ومعناه باليونانية: التعليم الجديد."], ["الفرقان", "ما فرق الله به بين الحق والباطل من الحجج القرآنية والمعجزات الإلهية والعقول النيّرة."], ["يصوّركم في الأرحام", "التصوير: إيجاد صورة للشيء لم تكن له من قبل، والأرحام: مستودع الجنين."]], "m": "أخرج ابن جرير الطبري أن وفد نجران، ستين راكباً فيهم أشرافهم، قدموا على رسول الله ﷺ يحاجّونه في أمر المسيح ﵇ يريدون إثبات ألوهيته، فأنزل الله نيّفاً وثمانين آية من فاتحة هذه السورة ردّاً لباطلهم وإقامة للحجة عليهم. فقال: «الله لا إله إلا هو» فأبطل عبادة المسيح وكل معبود سواه، ثم ذكر برهان استحقاقه للعبادة: «الحي» حياة أزلية أبدية، وكل حيّ غيره مسبوق بالعدم ويلحقه الفناء، والمسيح كذلك فكيف يكون إلهاً؟ «القيوم» القائم على الخلق بالتربية والرعاية والرزق، وما عداه مربوب مرزوق. ودليل ذلك أنه نزّل عليك القرآن بالحق، آياته كلها مثبتة الألوهية لله نافية لها عمّا سواه، مصدقاً لما قبله من الكتب، وأنزل التوراة والإنجيل هدى للناس، وأنزل الفرقان. وما أحياه عيسى ﵇ من الموتى وما أبرأه من الأكمه والأبرص كان بقدرة الله وإذنه. ولما ردّ الوفد الحجة تأكد كفرهم، فتوعّدهم: «إن الذين كفروا بآيات الله لهم عذاب شديد والله عزيز ذو انتقام». وأخبر أنه لا يخفى عليه شيء في الأرض ولا في السماء، وذكر دليلاً آخر: «هو الذي يصوّركم في الأرحام كيف يشاء»، وعيسى ﵇ قد صُوّر في رحم مريم، فكيف يكون إلهاً أو ابناً لله؟ «لا إله إلا هو العزيز الحكيم».", "h": ["تقرير ألوهية الله بالبراهين، ونفي الألوهية عن غيره من سائر خلقه.", "ثبوت رسالة النبي محمد ﷺ بإنزال الله الكتاب عليه.", "إقامة الله الحجة على عباده بإنزال كتبه والفرقان فيها بين الحق والباطل في كل شؤون الحياة.", "بطلان ألوهية المسيح؛ لأنه مخلوق مصوَّر في الأرحام كغيره، فكيف يكون إلهاً مع الله أو ابناً له؟ تعالى الله عن ذلك علواً كبيراً."], "k": "«هو الذي يصوّركم في الأرحام كيف يشاء»… هل شكرتُ ربي يوماً على الصورة التي خلقني عليها؟"}, {"lbl": "الآيات ٧ – ٩", "q": "هُوَ ٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ مِنۡهُ ءَايَٰتٞ مُّحۡكَمَٰتٌ هُنَّ أُمُّ ٱلۡكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٞۖ فَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغٞ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنۡهُ ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَآءَ تَأۡوِيلِهِۦۖ وَمَا يَعۡلَمُ تَأۡوِيلَهُۥٓ إِلَّا ٱللَّهُۗ وَٱلرَّـٰسِخُونَ فِي ٱلۡعِلۡمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلّٞ مِّنۡ عِندِ رَبِّنَاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿٧﴾ رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ ﴿٨﴾ رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوۡمٖ لَّا رَيۡبَ فِيهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ ﴿٩﴾", "w": [["محكمات", "ظاهرة الدلالة بيّنة المعنى لا تحتمل إلا معنى واحداً، كآيات الأحكام من حلال وحرام وحدود وعبادات وعبر وعظات."], ["متشابهات", "غير ظاهرة الدلالة، تحتمل معاني يصعب على غير الراسخين في العلم القول فيها، كفواتح السور وأمور الغيب."], ["في قلوبهم زيغ", "ميل عن الحق."], ["ابتغاء الفتنة", "طلباً لفتنة المؤمنين في دينهم ومعتقداتهم."], ["ابتغاء تأويله", "طلباً لتأويله ليوافق معتقداتهم الفاسدة."], ["وما يعلم تأويله إلا الله", "وما يعلم ما يؤول إليه أمر المتشابه إلا الله منزله."], ["الراسخون في العلم", "أهل العلم الذين ثبتت أقدامهم فيه."], ["كلٌّ من عند ربنا", "المحكم والمتشابه، فنؤمن به جميعاً."], ["أولو الألباب", "أصحاب العقول الراجحة والفهوم السليمة."], ["لا تُزغ قلوبنا", "لا تُمِل قلوبنا عن الحق بعد إذ هديتنا إليه."], ["هب لنا من لدنك", "أعطنا من عندك."]], "m": "ما زال الله يقرر ربوبيته وألوهيته ونبوة رسوله، ويبطل دعوى نصارى نجران في ألوهية المسيح ﵇: هو الذي أنزل عليك القرآن، منه آيات محكمات لا خفاء في معناها، وهي معظم آيه وأصله، ومنه آيات أُخر متشابهات وهي قليلة، والحكمة من إنزالها كذلك الامتحان والاختبار، ليثبت على الهداية من شاء الله هدايته، ويزيغ من شاء ضلاله. فأما الذين في قلوبهم ميل عن الحق فيتبعون المتشابه طلباً لفتنة المؤمنين ولتأويله على أهوائهم، كما فعل النصارى إذ قالوا: إن الله ثالث ثلاثة لأنه يقول: «خلقنا» و«نحيي» و«نميت» وهذا كلام جماعة، وقالوا في قوله عن عيسى «وروح منه» إنه جزء منه، وكما فعل الخوارج في قوله «إن الحكم إلا لله» فكفّروا علياً رضي الله عنه حين حكّم أبا موسى الأشعري. وهكذا يقع أهل الزيغ في الضلال، لأنهم لا يردّون المتشابه إلى المحكم. وأخبر أنه لا يعلم تأويله إلا هو، وأن الراسخين في العلم يفوّضون أمره إلى الله ويقولون: «آمنا به كل من عند ربنا»، ويسألون ربهم الثبات: «ربنا لا تزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة إنك أنت الوهاب»، ويقرّون بالمعاد: «ربنا إنك جامع الناس ليوم لا ريب فيه» لمحاسبتهم، فاغفر لنا وارحمنا يومئذ، إنك لا تخلف الميعاد.", "h": ["في كتاب الله المحكم والمتشابه؛ فالمحكم يجب الإيمان به والعمل بمقتضاه، والمتشابه يجب الإيمان به ويُفوَّض تأويله إلى الله، ويقال: «آمنا به كل من عند ربنا».", "أهل الزيغ الذين يتبعون ما تشابه يجب هجرانهم والإعراض عنهم؛ لأنهم مبتدعة وأهل أهواء.", "استحباب الدعاء بطلب النجاة عند ظهور الزيغ ورؤية الفتن والضلال.", "تقرير مبدأ المعاد والدار الآخرة."], "k": "«ربنا لا تزغ قلوبنا بعد إذ هديتنا»… هل أخاف على قلبي من الزيغ، فأدعو بها كل يوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 43;
insert into public.tdb_cards(topic, i, body) select 43, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٦", "q": "الٓمٓ ﴿١﴾ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُ ﴿٢﴾ نَزَّلَ عَلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَأَنزَلَ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ ﴿٣﴾ مِن قَبۡلُ هُدٗى لِّلنَّاسِ وَأَنزَلَ ٱلۡفُرۡقَانَۗ إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدٞۗ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ ﴿٤﴾ إِنَّ ٱللَّهَ لَا يَخۡفَىٰ عَلَيۡهِ شَيۡءٞ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ ﴿٥﴾ هُوَ ٱلَّذِي يُصَوِّرُكُمۡ فِي ٱلۡأَرۡحَامِ كَيۡفَ يَشَآءُۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٦﴾", "w": [["الله", "المعبود بحق."], ["لا إله إلا هو", "لا معبود بحق سواه."], ["الحيّ", "ذو الحياة المستلزمة للإرادة والعلم والسمع والبصر والقدرة."], ["القيّوم", "القائم على كل مخلوقاته بالتربية والرعاية والحفظ."], ["الكتاب", "القرآن."], ["بالحق", "متلبّساً به؛ إذ كل ما فيه حق وصدق لا باطل فيه بوجه من الوجوه."], ["مصدقاً لما بين يديه", "من الكتب السابقة، لا يخالفها ولا يبطلها؛ لأن مصدر الجميع واحد هو الله."], ["التوراة", "كتاب موسى ﵇، ومعناها بالعبرية: الشريعة."], ["الإنجيل", "كتاب عيسى ﵇، ومعناه باليونانية: التعليم الجديد."], ["الفرقان", "ما فرق الله به بين الحق والباطل من الحجج القرآنية والمعجزات الإلهية والعقول النيّرة."], ["يصوّركم في الأرحام", "التصوير: إيجاد صورة للشيء لم تكن له من قبل، والأرحام: مستودع الجنين."]], "m": "أخرج ابن جرير الطبري أن وفد نجران، ستين راكباً فيهم أشرافهم، قدموا على رسول الله ﷺ يحاجّونه في أمر المسيح ﵇ يريدون إثبات ألوهيته، فأنزل الله نيّفاً وثمانين آية من فاتحة هذه السورة ردّاً لباطلهم وإقامة للحجة عليهم. فقال: «الله لا إله إلا هو» فأبطل عبادة المسيح وكل معبود سواه، ثم ذكر برهان استحقاقه للعبادة: «الحي» حياة أزلية أبدية، وكل حيّ غيره مسبوق بالعدم ويلحقه الفناء، والمسيح كذلك فكيف يكون إلهاً؟ «القيوم» القائم على الخلق بالتربية والرعاية والرزق، وما عداه مربوب مرزوق. ودليل ذلك أنه نزّل عليك القرآن بالحق، آياته كلها مثبتة الألوهية لله نافية لها عمّا سواه، مصدقاً لما قبله من الكتب، وأنزل التوراة والإنجيل هدى للناس، وأنزل الفرقان. وما أحياه عيسى ﵇ من الموتى وما أبرأه من الأكمه والأبرص كان بقدرة الله وإذنه. ولما ردّ الوفد الحجة تأكد كفرهم، فتوعّدهم: «إن الذين كفروا بآيات الله لهم عذاب شديد والله عزيز ذو انتقام». وأخبر أنه لا يخفى عليه شيء في الأرض ولا في السماء، وذكر دليلاً آخر: «هو الذي يصوّركم في الأرحام كيف يشاء»، وعيسى ﵇ قد صُوّر في رحم مريم، فكيف يكون إلهاً أو ابناً لله؟ «لا إله إلا هو العزيز الحكيم».", "h": ["تقرير ألوهية الله بالبراهين، ونفي الألوهية عن غيره من سائر خلقه.", "ثبوت رسالة النبي محمد ﷺ بإنزال الله الكتاب عليه.", "إقامة الله الحجة على عباده بإنزال كتبه والفرقان فيها بين الحق والباطل في كل شؤون الحياة.", "بطلان ألوهية المسيح؛ لأنه مخلوق مصوَّر في الأرحام كغيره، فكيف يكون إلهاً مع الله أو ابناً له؟ تعالى الله عن ذلك علواً كبيراً."], "k": "«هو الذي يصوّركم في الأرحام كيف يشاء»… هل شكرتُ ربي يوماً على الصورة التي خلقني عليها؟"}, {"lbl": "الآيات ٧ – ٩", "q": "هُوَ ٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ مِنۡهُ ءَايَٰتٞ مُّحۡكَمَٰتٌ هُنَّ أُمُّ ٱلۡكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٞۖ فَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغٞ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنۡهُ ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَآءَ تَأۡوِيلِهِۦۖ وَمَا يَعۡلَمُ تَأۡوِيلَهُۥٓ إِلَّا ٱللَّهُۗ وَٱلرَّـٰسِخُونَ فِي ٱلۡعِلۡمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلّٞ مِّنۡ عِندِ رَبِّنَاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿٧﴾ رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ ﴿٨﴾ رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوۡمٖ لَّا رَيۡبَ فِيهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ ﴿٩﴾", "w": [["محكمات", "ظاهرة الدلالة بيّنة المعنى لا تحتمل إلا معنى واحداً، كآيات الأحكام من حلال وحرام وحدود وعبادات وعبر وعظات."], ["متشابهات", "غير ظاهرة الدلالة، تحتمل معاني يصعب على غير الراسخين في العلم القول فيها، كفواتح السور وأمور الغيب."], ["في قلوبهم زيغ", "ميل عن الحق."], ["ابتغاء الفتنة", "طلباً لفتنة المؤمنين في دينهم ومعتقداتهم."], ["ابتغاء تأويله", "طلباً لتأويله ليوافق معتقداتهم الفاسدة."], ["وما يعلم تأويله إلا الله", "وما يعلم ما يؤول إليه أمر المتشابه إلا الله منزله."], ["الراسخون في العلم", "أهل العلم الذين ثبتت أقدامهم فيه."], ["كلٌّ من عند ربنا", "المحكم والمتشابه، فنؤمن به جميعاً."], ["أولو الألباب", "أصحاب العقول الراجحة والفهوم السليمة."], ["لا تُزغ قلوبنا", "لا تُمِل قلوبنا عن الحق بعد إذ هديتنا إليه."], ["هب لنا من لدنك", "أعطنا من عندك."]], "m": "ما زال الله يقرر ربوبيته وألوهيته ونبوة رسوله، ويبطل دعوى نصارى نجران في ألوهية المسيح ﵇: هو الذي أنزل عليك القرآن، منه آيات محكمات لا خفاء في معناها، وهي معظم آيه وأصله، ومنه آيات أُخر متشابهات وهي قليلة، والحكمة من إنزالها كذلك الامتحان والاختبار، ليثبت على الهداية من شاء الله هدايته، ويزيغ من شاء ضلاله. فأما الذين في قلوبهم ميل عن الحق فيتبعون المتشابه طلباً لفتنة المؤمنين ولتأويله على أهوائهم، كما فعل النصارى إذ قالوا: إن الله ثالث ثلاثة لأنه يقول: «خلقنا» و«نحيي» و«نميت» وهذا كلام جماعة، وقالوا في قوله عن عيسى «وروح منه» إنه جزء منه، وكما فعل الخوارج في قوله «إن الحكم إلا لله» فكفّروا علياً رضي الله عنه حين حكّم أبا موسى الأشعري. وهكذا يقع أهل الزيغ في الضلال، لأنهم لا يردّون المتشابه إلى المحكم. وأخبر أنه لا يعلم تأويله إلا هو، وأن الراسخين في العلم يفوّضون أمره إلى الله ويقولون: «آمنا به كل من عند ربنا»، ويسألون ربهم الثبات: «ربنا لا تزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة إنك أنت الوهاب»، ويقرّون بالمعاد: «ربنا إنك جامع الناس ليوم لا ريب فيه» لمحاسبتهم، فاغفر لنا وارحمنا يومئذ، إنك لا تخلف الميعاد.", "h": ["في كتاب الله المحكم والمتشابه؛ فالمحكم يجب الإيمان به والعمل بمقتضاه، والمتشابه يجب الإيمان به ويُفوَّض تأويله إلى الله، ويقال: «آمنا به كل من عند ربنا».", "أهل الزيغ الذين يتبعون ما تشابه يجب هجرانهم والإعراض عنهم؛ لأنهم مبتدعة وأهل أهواء.", "استحباب الدعاء بطلب النجاة عند ظهور الزيغ ورؤية الفتن والضلال.", "تقرير مبدأ المعاد والدار الآخرة."], "k": "«ربنا لا تزغ قلوبنا بعد إذ هديتنا»… هل أخاف على قلبي من الزيغ، فأدعو بها كل يوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (44, 3, 10, 17, 'سورة آل عمران ١٠ – ١٧', 'عاقبة الكفر، وزينة الدنيا، وخيرٌ منها للمتقين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 44) = $j$[{"lbl": "الآيات ١٠ – ١٣", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَـٰٓئِكَ هُمۡ وَقُودُ ٱلنَّارِ ﴿١٠﴾ كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۗ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ ﴿١١﴾ قُل لِّلَّذِينَ كَفَرُواْ سَتُغۡلَبُونَ وَتُحۡشَرُونَ إِلَىٰ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمِهَادُ ﴿١٢﴾ قَدۡ كَانَ لَكُمۡ ءَايَةٞ فِي فِئَتَيۡنِ ٱلۡتَقَتَاۖ فِئَةٞ تُقَٰتِلُ فِي سَبِيلِ ٱللَّهِ وَأُخۡرَىٰ كَافِرَةٞ يَرَوۡنَهُم مِّثۡلَيۡهِمۡ رَأۡيَ ٱلۡعَيۡنِۚ وَٱللَّهُ يُؤَيِّدُ بِنَصۡرِهِۦ مَن يَشَآءُۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ ﴿١٣﴾", "w": [["إن الذين كفروا", "هم وفد نجران ويهود المدينة والمشركون والمنافقون."], ["لن تغني عنهم", "لن تجزي عنهم ولن تقيهم عذاب الله إذا حلّ بهم."], ["وقود النار", "ما تُوقد به النار من حطب ونحوه."], ["كدأب آل فرعون", "كعادتهم وسنّتهم في كفرهم وتكذيبهم وما حلّ بهم من عذاب في الدنيا والآخرة."], ["قل للذين كفروا", "هم يهود المدينة بنو قينقاع."], ["آية في فئتين", "علامة واضحة، والفئتان: المسلمون وقريش التقتا في بدر."], ["يؤيّد", "يقوّي."], ["عبرة لأولي الأبصار", "العبرة: العظة وما يعبر به ذو البصيرة مواضع الخطر فينجو."]], "m": "لما أصرّ وفد نجران على الكفر واتباع المتشابه، توعّد الله جنس الكافرين الذين عرفوا الحق فمنعهم من قبوله الحفاظ على المناصب والمنافع: لن تغني عنهم أموالهم ولا أولادهم من الله شيئاً، وأولئك هم وقود النار. وهم في كفرهم وعنادهم كدأب آل فرعون والذين من قبلهم من الأمم المكذّبة، كقوم نوح وهود وصالح، أخذهم الله بذنوبهم في الدنيا بالهلاك، وفي الآخرة بالنار.\nثم أمر رسوله ﷺ أن يقول ليهود المدينة الذين هدّدوه بقولهم: لا يغرّنك أنك قاتلت قوماً لا يحسنون الحرب، إنك إن قاتلتنا علمت أنّا نحن الناس: «ستُغلبون وتُحشرون إلى جهنم وبئس المهاد». وفتح أعينهم على حقيقة لو تأملوها لما تورّطوا في حربه: أن المسلمين في بدر كانوا أقل عدداً وعدة، ومع ذلك انتصروا لأنهم يقاتلون في سبيل الله، والكافرون يقاتلون في سبيل الطاغوت، يرونهم مثليهم رأي العين، والله يؤيد بنصره من يشاء، وفي ذلك عبرة لمن كان ذا بصيرة.", "h": ["الكفر مورث لعذاب يوم القيامة، والكافر معذّب قطعاً.", "الأموال والأولاد والرجال والعتاد مهما كثرت لن تغني من بأس الله شيئاً إذا أراده بالكافرين.", "الذنوب بريد العذاب العاجل والآجل.", "ذم الفخر والتعالي، وسوء عاقبتهما.", "العاقل من اعتبر بغيره، ولا عبرة لغير أولي البصائر.", "صدق خبر القرآن فيما أخبر به اليهود من هزيمتهم، فكان دليلاً على أن القرآن وحي الله، وأن محمداً رسول الله، وأن الإسلام دين الله الحق."], "k": "القلة المؤمنة غلبت الكثرة الكافرة في بدر… فهل أنظر في حياتي إلى الأسباب وحدها وأنسى «والله يؤيّد بنصره من يشاء»؟"}, {"lbl": "الآية ١٤", "q": "زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ ﴿١٤﴾", "w": [["زُيّن للناس حب الشهوات", "جُعل حبها مستحسناً في نفوسهم لا يرون فيه قبحاً."], ["الشهوات", "جمع شهوة بمعنى المُشتهى طبعاً وغريزة، كالطعام والشراب اللذيذين."], ["القناطير المقنطرة", "القنطار ألف ومائة أوقية فضة، والمقنطرة: الكثيرة بعضها فوق بعض."], ["الخيل المسوّمة", "ذات السمات الحسان، المعدّة للركوب عليها للغزو والجهاد."], ["الأنعام", "الإبل والبقر والغنم."], ["الحرث", "الزروع والحقول وسائر النباتات النافعة."], ["متاع الحياة الدنيا", "ما يُستمتع به فيها ثم يموت صاحبه ويتركه."], ["حسن المآب", "المرجع الحسن."]], "m": "لما ذكر الله عناد من كفر من النصارى واليهود والمشركين، ذكر علّة الكفر وسببه: ما زيّنه الله لبني البشر ليفتنهم فيه ويمتحنهم به، وهو حب المشتهيات بالطبع البشري: النساء والبنين، والقناطير المقنطرة من الذهب والفضة، والخيل المسوّمة، والأنعام، والحرث. هذا الذي جعل تلك الجماعات ترفض الحق، لأنه يحول بينهم وبين هذه المشتهيات غالباً، ولم يعلموا أنها مجرد متاع زائل فلا يبيعون بها الجنة دار الخلد. ولذا قال: «ذلك متاع الحياة الدنيا» لا غير، أما الآخرة فلا ينفع فيها شيء من ذلك إلا ما كان بُلغة إلى عملها من الإيمان وصالح الأعمال. وختم الآية مرغّباً في العمل للآخرة، داعياً عباده إلى الزهد في المتاع الفاني لتتعلق قلوبهم بالنعيم الباقي: «والله عنده حسن المآب».", "h": ["يزيّن الله الشيء بمعنى يجعله زيناً محبوباً للابتلاء والاختبار، ويزيّن الشيطان للإضلال والإغواء؛ فالله يزيّن الزين ويقبّح القبيح، والشيطان يزيّن القبيح ويقبّح الزين.", "المزيَّنات في هذه الآية من تزيين الله للابتلاء، وكلها زينة في الواقع، إلا إذا طُلبت من غير حِلّها، أو أُخذت بشره ونهم فأفسدت أخلاق آخذها، أو طغت عليه محبتها فأنسته لقاء الله.", "كل ما في الدنيا مجرد متاع، والمتاع دائماً قليل وزائل، فعلى العاقل أن ينظر إليه كما هو، فلا يطلبه بما يحرمه حسن المآب عند الله."], "k": "من هذه الزينة: ما الذي يأخذ من قلبي أكثر مما يستحق؟"}, {"lbl": "الآيات ١٥ – ١٧", "q": "۞قُلۡ أَؤُنَبِّئُكُم بِخَيۡرٖ مِّن ذَٰلِكُمۡۖ لِلَّذِينَ ٱتَّقَوۡاْ عِندَ رَبِّهِمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَأَزۡوَٰجٞ مُّطَهَّرَةٞ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ ﴿١٥﴾ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ ﴿١٦﴾ ٱلصَّـٰبِرِينَ وَٱلصَّـٰدِقِينَ وَٱلۡقَٰنِتِينَ وَٱلۡمُنفِقِينَ وَٱلۡمُسۡتَغۡفِرِينَ بِٱلۡأَسۡحَارِ ﴿١٧﴾", "w": [["أؤنبّئكم", "أخبركم بنبأ عظيم؛ لأن النبأ لا يكون إلا في الأمر العظيم."], ["بخير من ذلكم", "من المذكور في الآية السابقة من النساء والبنين إلى آخره."], ["اتقوا", "خافوا ربهم فتركوا الشرك به ومعصيته ومعصية رسوله."], ["تجري من تحتها الأنهار", "من خلال قصورها وأشجارها أنهار الماء واللبن والعسل والخمر."], ["خالدين فيها", "مقيمين فيها إقامة لا يرحلون بعدها أبداً."], ["أزواج مطهّرة", "زوجات من الحور العين، نقيّات من الحيض والبول وكل أذى وقذر."], ["الصابرين", "على الطاعات لا يفارقونها، وعلى المكروه لا يتسخّطون، وعن المعاصي لا يقربونها."]], "m": "لما بيّن الله ما زيّنه للناس من حب الشهوات، وأن حسن المآب عنده، بيّنه بقوله: للذين اتقوا عند ربهم جنات تجري من تحتها الأنهار خالدين فيها، وأزواج مطهّرة، ورضوان من الله، وهو رضاه عنهم وهو أكبر من كل نعيم قبله. ثم أخبر أنه بصير بعباده، يعلم المؤمن الصادق والمنافق الكاذب، وسيجزي كلاً بعدله وفضله. ثم ذكر صفات المتقين التي ورثوا بها هذا النعيم: «الذين يقولون ربنا إننا آمنا فاغفر لنا ذنوبنا وقنا عذاب النار»، فذكر الإيمان والخشية والضراعة والدعاء، ثم سائر الصفات: الصابرين والصادقين والقانتين والمنفقين والمستغفرين بالأسحار، يتهجدون آخر الليل وقُبيل الفجر ويكثرون من طلب المغفرة.", "h": ["نعيم الآخرة خير من نعيم الدنيا مهما كان.", "نعيم الآخرة خاص بالمتقين الأبرار، ونعيم الدنيا غالباً ما يكون للفجّار.", "التقوى، وهي ترك الشرك والمعاصي، هي سبب وراثة دار السلام.", "استحباب الضراعة والدعاء والاستغفار في آخر الليل.", "الصفات المذكورة لأهل التقوى هنا كلها واجبة في الجملة، لا يحل لمؤمن ولا مؤمنة ألا يتصف بها."], "k": "«والمستغفرين بالأسحار»… متى كانت آخر مرة استيقظت قبل الفجر لأستغفر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 44;
insert into public.tdb_cards(topic, i, body) select 44, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠ – ١٣", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَـٰٓئِكَ هُمۡ وَقُودُ ٱلنَّارِ ﴿١٠﴾ كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۗ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ ﴿١١﴾ قُل لِّلَّذِينَ كَفَرُواْ سَتُغۡلَبُونَ وَتُحۡشَرُونَ إِلَىٰ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمِهَادُ ﴿١٢﴾ قَدۡ كَانَ لَكُمۡ ءَايَةٞ فِي فِئَتَيۡنِ ٱلۡتَقَتَاۖ فِئَةٞ تُقَٰتِلُ فِي سَبِيلِ ٱللَّهِ وَأُخۡرَىٰ كَافِرَةٞ يَرَوۡنَهُم مِّثۡلَيۡهِمۡ رَأۡيَ ٱلۡعَيۡنِۚ وَٱللَّهُ يُؤَيِّدُ بِنَصۡرِهِۦ مَن يَشَآءُۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ ﴿١٣﴾", "w": [["إن الذين كفروا", "هم وفد نجران ويهود المدينة والمشركون والمنافقون."], ["لن تغني عنهم", "لن تجزي عنهم ولن تقيهم عذاب الله إذا حلّ بهم."], ["وقود النار", "ما تُوقد به النار من حطب ونحوه."], ["كدأب آل فرعون", "كعادتهم وسنّتهم في كفرهم وتكذيبهم وما حلّ بهم من عذاب في الدنيا والآخرة."], ["قل للذين كفروا", "هم يهود المدينة بنو قينقاع."], ["آية في فئتين", "علامة واضحة، والفئتان: المسلمون وقريش التقتا في بدر."], ["يؤيّد", "يقوّي."], ["عبرة لأولي الأبصار", "العبرة: العظة وما يعبر به ذو البصيرة مواضع الخطر فينجو."]], "m": "لما أصرّ وفد نجران على الكفر واتباع المتشابه، توعّد الله جنس الكافرين الذين عرفوا الحق فمنعهم من قبوله الحفاظ على المناصب والمنافع: لن تغني عنهم أموالهم ولا أولادهم من الله شيئاً، وأولئك هم وقود النار. وهم في كفرهم وعنادهم كدأب آل فرعون والذين من قبلهم من الأمم المكذّبة، كقوم نوح وهود وصالح، أخذهم الله بذنوبهم في الدنيا بالهلاك، وفي الآخرة بالنار.\nثم أمر رسوله ﷺ أن يقول ليهود المدينة الذين هدّدوه بقولهم: لا يغرّنك أنك قاتلت قوماً لا يحسنون الحرب، إنك إن قاتلتنا علمت أنّا نحن الناس: «ستُغلبون وتُحشرون إلى جهنم وبئس المهاد». وفتح أعينهم على حقيقة لو تأملوها لما تورّطوا في حربه: أن المسلمين في بدر كانوا أقل عدداً وعدة، ومع ذلك انتصروا لأنهم يقاتلون في سبيل الله، والكافرون يقاتلون في سبيل الطاغوت، يرونهم مثليهم رأي العين، والله يؤيد بنصره من يشاء، وفي ذلك عبرة لمن كان ذا بصيرة.", "h": ["الكفر مورث لعذاب يوم القيامة، والكافر معذّب قطعاً.", "الأموال والأولاد والرجال والعتاد مهما كثرت لن تغني من بأس الله شيئاً إذا أراده بالكافرين.", "الذنوب بريد العذاب العاجل والآجل.", "ذم الفخر والتعالي، وسوء عاقبتهما.", "العاقل من اعتبر بغيره، ولا عبرة لغير أولي البصائر.", "صدق خبر القرآن فيما أخبر به اليهود من هزيمتهم، فكان دليلاً على أن القرآن وحي الله، وأن محمداً رسول الله، وأن الإسلام دين الله الحق."], "k": "القلة المؤمنة غلبت الكثرة الكافرة في بدر… فهل أنظر في حياتي إلى الأسباب وحدها وأنسى «والله يؤيّد بنصره من يشاء»؟"}, {"lbl": "الآية ١٤", "q": "زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ ﴿١٤﴾", "w": [["زُيّن للناس حب الشهوات", "جُعل حبها مستحسناً في نفوسهم لا يرون فيه قبحاً."], ["الشهوات", "جمع شهوة بمعنى المُشتهى طبعاً وغريزة، كالطعام والشراب اللذيذين."], ["القناطير المقنطرة", "القنطار ألف ومائة أوقية فضة، والمقنطرة: الكثيرة بعضها فوق بعض."], ["الخيل المسوّمة", "ذات السمات الحسان، المعدّة للركوب عليها للغزو والجهاد."], ["الأنعام", "الإبل والبقر والغنم."], ["الحرث", "الزروع والحقول وسائر النباتات النافعة."], ["متاع الحياة الدنيا", "ما يُستمتع به فيها ثم يموت صاحبه ويتركه."], ["حسن المآب", "المرجع الحسن."]], "m": "لما ذكر الله عناد من كفر من النصارى واليهود والمشركين، ذكر علّة الكفر وسببه: ما زيّنه الله لبني البشر ليفتنهم فيه ويمتحنهم به، وهو حب المشتهيات بالطبع البشري: النساء والبنين، والقناطير المقنطرة من الذهب والفضة، والخيل المسوّمة، والأنعام، والحرث. هذا الذي جعل تلك الجماعات ترفض الحق، لأنه يحول بينهم وبين هذه المشتهيات غالباً، ولم يعلموا أنها مجرد متاع زائل فلا يبيعون بها الجنة دار الخلد. ولذا قال: «ذلك متاع الحياة الدنيا» لا غير، أما الآخرة فلا ينفع فيها شيء من ذلك إلا ما كان بُلغة إلى عملها من الإيمان وصالح الأعمال. وختم الآية مرغّباً في العمل للآخرة، داعياً عباده إلى الزهد في المتاع الفاني لتتعلق قلوبهم بالنعيم الباقي: «والله عنده حسن المآب».", "h": ["يزيّن الله الشيء بمعنى يجعله زيناً محبوباً للابتلاء والاختبار، ويزيّن الشيطان للإضلال والإغواء؛ فالله يزيّن الزين ويقبّح القبيح، والشيطان يزيّن القبيح ويقبّح الزين.", "المزيَّنات في هذه الآية من تزيين الله للابتلاء، وكلها زينة في الواقع، إلا إذا طُلبت من غير حِلّها، أو أُخذت بشره ونهم فأفسدت أخلاق آخذها، أو طغت عليه محبتها فأنسته لقاء الله.", "كل ما في الدنيا مجرد متاع، والمتاع دائماً قليل وزائل، فعلى العاقل أن ينظر إليه كما هو، فلا يطلبه بما يحرمه حسن المآب عند الله."], "k": "من هذه الزينة: ما الذي يأخذ من قلبي أكثر مما يستحق؟"}, {"lbl": "الآيات ١٥ – ١٧", "q": "۞قُلۡ أَؤُنَبِّئُكُم بِخَيۡرٖ مِّن ذَٰلِكُمۡۖ لِلَّذِينَ ٱتَّقَوۡاْ عِندَ رَبِّهِمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَأَزۡوَٰجٞ مُّطَهَّرَةٞ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ ﴿١٥﴾ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ ﴿١٦﴾ ٱلصَّـٰبِرِينَ وَٱلصَّـٰدِقِينَ وَٱلۡقَٰنِتِينَ وَٱلۡمُنفِقِينَ وَٱلۡمُسۡتَغۡفِرِينَ بِٱلۡأَسۡحَارِ ﴿١٧﴾", "w": [["أؤنبّئكم", "أخبركم بنبأ عظيم؛ لأن النبأ لا يكون إلا في الأمر العظيم."], ["بخير من ذلكم", "من المذكور في الآية السابقة من النساء والبنين إلى آخره."], ["اتقوا", "خافوا ربهم فتركوا الشرك به ومعصيته ومعصية رسوله."], ["تجري من تحتها الأنهار", "من خلال قصورها وأشجارها أنهار الماء واللبن والعسل والخمر."], ["خالدين فيها", "مقيمين فيها إقامة لا يرحلون بعدها أبداً."], ["أزواج مطهّرة", "زوجات من الحور العين، نقيّات من الحيض والبول وكل أذى وقذر."], ["الصابرين", "على الطاعات لا يفارقونها، وعلى المكروه لا يتسخّطون، وعن المعاصي لا يقربونها."]], "m": "لما بيّن الله ما زيّنه للناس من حب الشهوات، وأن حسن المآب عنده، بيّنه بقوله: للذين اتقوا عند ربهم جنات تجري من تحتها الأنهار خالدين فيها، وأزواج مطهّرة، ورضوان من الله، وهو رضاه عنهم وهو أكبر من كل نعيم قبله. ثم أخبر أنه بصير بعباده، يعلم المؤمن الصادق والمنافق الكاذب، وسيجزي كلاً بعدله وفضله. ثم ذكر صفات المتقين التي ورثوا بها هذا النعيم: «الذين يقولون ربنا إننا آمنا فاغفر لنا ذنوبنا وقنا عذاب النار»، فذكر الإيمان والخشية والضراعة والدعاء، ثم سائر الصفات: الصابرين والصادقين والقانتين والمنفقين والمستغفرين بالأسحار، يتهجدون آخر الليل وقُبيل الفجر ويكثرون من طلب المغفرة.", "h": ["نعيم الآخرة خير من نعيم الدنيا مهما كان.", "نعيم الآخرة خاص بالمتقين الأبرار، ونعيم الدنيا غالباً ما يكون للفجّار.", "التقوى، وهي ترك الشرك والمعاصي، هي سبب وراثة دار السلام.", "استحباب الضراعة والدعاء والاستغفار في آخر الليل.", "الصفات المذكورة لأهل التقوى هنا كلها واجبة في الجملة، لا يحل لمؤمن ولا مؤمنة ألا يتصف بها."], "k": "«والمستغفرين بالأسحار»… متى كانت آخر مرة استيقظت قبل الفجر لأستغفر؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (45, 3, 18, 25, 'سورة آل عمران ١٨ – ٢٥', 'إن الدين عند الله الإسلام', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 45) = $j$[{"lbl": "الآيات ١٨ – ٢٠", "q": "شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلۡمَلَـٰٓئِكَةُ وَأُوْلُواْ ٱلۡعِلۡمِ قَآئِمَۢا بِٱلۡقِسۡطِۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿١٨﴾ إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ وَمَا ٱخۡتَلَفَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۗ وَمَن يَكۡفُرۡ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ﴿١٩﴾ فَإِنۡ حَآجُّوكَ فَقُلۡ أَسۡلَمۡتُ وَجۡهِيَ لِلَّهِ وَمَنِ ٱتَّبَعَنِۗ وَقُل لِّلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡأُمِّيِّـۧنَ ءَأَسۡلَمۡتُمۡۚ فَإِنۡ أَسۡلَمُواْ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ ﴿٢٠﴾", "w": [["شهد", "أخبر عن علم بحضوره الأمر المشهود به."], ["لا إله إلا هو", "لا معبود بحق في الأرض ولا في السماء إلا الله."], ["أولو العلم", "أصحاب العلم الصحيح المطابق للواقع، وهم الأنبياء والعلماء."], ["القسط", "العدل في الحكم والقول والعمل."], ["العزيز الحكيم", "الغالب ذو العزة التي لا تُغلب، الحكيم في كل خلقه وفعله وتصرفه."], ["الدين", "ما يُدان لله به، أي يُطاع فيه ويُخضع له به من الشرائع والعبادات."], ["الإسلام", "الانقياد لله بالطاعة والخلوص من الشرك، والمراد به هنا ملة الإسلام."], ["بغياً", "ظلماً وحسداً."], ["حاجّوك", "جادلوك وخاصموك بحجج باطلة."], ["أسلمت وجهي لله", "أخلصت أعمالي القلبية والبدنية لله وحده لا شريك له."], ["أوتوا الكتاب", "اليهود والنصارى."], ["الأميين", "العرب المشركين، سُمّوا بذلك لقلة من يقرأ ويكتب فيهم."], ["أأسلمتم", "استفهام المراد به الأمر: أسلِموا خيراً لكم."], ["وإن تولّوا", "أدبروا عن الحق بعد رؤيته، فلا يضرّك أمرهم إذ ما عليك إلا البلاغ."]], "m": "يخبر الله أنه شهد أنه لا إله إلا هو، وأن الملائكة وأولي العلم يشهدون كذلك شهادة علم وحق، وأنه قائم في الملكوت كله بالعدل، العزيز في ملكه، الحكيم في تدبيره؛ فردّ بهذه الشهادة باطل نصارى نجران ومكر اليهود وشرك العرب. ثم أخبر أن الدين الحق الذي لا يقبل ديناً سواه هو الإسلام، القائم على الانقياد الكامل لله والخلوص من الشرك. وأخبر أن اختلاف أهل الكتاب لم يكن عن جهل بالحق، وإنما عن علم، حملهم عليه البغي والحسد؛ إذ كل فرقة تريد الرئاسة الدينية والدنيوية لها دون غيرها، وبذلك يفسد أمر الدين والدنيا، وهذه سنة بشرية تورّط فيها المسلمون أيضاً بعد القرون المفضلة. ومن يكفر بآيات الله فإن الله سريع الحساب، يحصي عليه ذنوبه ويجزيه. ثم قال لرسوله: فإن حاجّك وفد نجران فاختصر الجدال معهم بإظهار موقفك: «أسلمت وجهي لله ومن اتبعن»، فليس فينا شيء لغير الله، ثم ادعُ أهل الكتاب والأميين إلى الإسلام؛ فإن أسلموا فقد اهتدوا، وإن تولّوا فلا يضرّك إعراضهم، إنما عليك البلاغ، والله بصير بالعباد.", "h": ["اعتبار الشهادة والأخذ بها إن كانت قائمة على العلم، وكان الشاهد أهلاً لذلك بأن كان مسلماً عدلاً.", "شهادة الله أعظم شهادة تثبت بها الشرائع والأحكام، وتليها شهادة الملائكة وأولي العلم.", "بطلان كل دين بعد الإسلام، وكل ملة غير ملته، لشهادة الله بذلك.", "الخلاف بين أهل العلم والدين يقع عندما يؤثرون الحياة الدنيا على الآخرة، فيتشوّفون إلى المناصب ويرغبون في الشرف، فيختلفون بغياً وحسداً.", "من أسلم قلبه وجوارحه لله، وأصبح وقفاً في حياته على الله، فقد اهتدى إلى سبيل النجاة والسلام.", "من علّق قلبه بالحياة الدنيا، وأعرض عما يصرفه عنها من العبادات، ضلّ في حياته وسعيه، وحسابه على الله."], "k": "«أسلمت وجهي لله»… هل في حياتي شيء أعطيه قلبي كله ولم أُسلمه بعدُ لله؟"}, {"lbl": "الآيتان ٢١ – ٢٢", "q": "إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ حَقّٖ وَيَقۡتُلُونَ ٱلَّذِينَ يَأۡمُرُونَ بِٱلۡقِسۡطِ مِنَ ٱلنَّاسِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ ﴿٢١﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِينَ ﴿٢٢﴾", "w": [["يكفرون", "يجحدون ويكذّبون."], ["النبيين", "جمع نبي، وهو ذكر من بني آدم أوحى الله إليه."], ["القسط", "العدل والحق والخير والمعروف."], ["فبشّرهم بعذاب أليم", "أخبرهم خبراً يظهر أثره على بشرة وجوههم ألماً وحسرة."], ["حبطت أعمالهم", "بطلت فلم ينتفعوا بها."], ["وما لهم من ناصرين", "لأن الله خذلهم وأراد إهلاكهم."]], "m": "ما زال السياق في هتك أستار الكفرة من أهل الكتابين، فذكر أن الذين يكفرون بآيات الله وحججه وما بعث به رسله، ويقتلون النبيين بغير حق، ويقتلون من يأمرونهم بالعدل من أتباع الأنبياء المؤمنين، هذه جرائم بعض أهل الكتاب، فبشّرهم بعذاب أليم. ثم أخبر أن أولئك حبطت أعمالهم في الدنيا، فلا يجنون منها عاقبة حسنة ولا ثناءً، والآخرة كذلك، وليس لهم من ناصرين يخلّصونهم من عذاب الله.", "h": ["الكفر والظلم من موجبات هلاك الدنيا ولزوم عذاب الآخرة.", "قتل الآمرين بالمعروف والناهين عن المنكر كقتل الأنبياء في عِظم الجرم.", "الشرك محبط للأعمال، مفسد لها في الدنيا والآخرة.", "من خذله الله لا ينصره أحد، ومن ينصره الله لا يغلبه أحد."], "k": "من يأمرني بالقسط وينصحني… هل أستقبل نصيحته بصدر رحب؟"}, {"lbl": "الآيات ٢٣ – ٢٥", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُدۡعَوۡنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحۡكُمَ بَيۡنَهُمۡ ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُمۡ وَهُم مُّعۡرِضُونَ ﴿٢٣﴾ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَٰتٖۖ وَغَرَّهُمۡ فِي دِينِهِم مَّا كَانُواْ يَفۡتَرُونَ ﴿٢٤﴾ فَكَيۡفَ إِذَا جَمَعۡنَٰهُمۡ لِيَوۡمٖ لَّا رَيۡبَ فِيهِ وَوُفِّيَتۡ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ ﴿٢٥﴾", "w": [["أوتوا نصيباً من الكتاب", "أُعطوا حظاً من التوراة."], ["يُدعون", "يُطلب منهم أن يتحاكموا فيما اختلفوا فيه إلى كتابهم الذي يؤمنون به، فيأبون ويعرضون."], ["يتولّى", "يرجع وهو مصمّم على عدم العودة إلى الحق."], ["أياماً معدودات", "قول اليهود، ويعنون أربعين يوماً، هي التي عبدوا فيها العجل بعد غياب موسى ﵇."], ["يفترون", "يكذبون."], ["ليوم لا ريب فيه", "يوم القيامة."], ["ما كسبت", "ما عملت من خير أو شر."], ["لا يُظلمون", "بأن يُعذّبوا بلا موجب من الشرك والكفر والمعاصي."]], "m": "ما زال السياق في فضح أهل الكتاب بذكر جرائمهم: ألم ينتهِ إلى علمك يا رسولنا أمر الذين أوتوا نصيباً من الكتاب، يُدعون إلى التحاكم إلى كتاب الله فيما اختلفوا فيه من صفاتك وشأن نبوتك، ثم يتولّى فريق منهم وهم مصمّمون على الإعراض؟ إنها حال تدعو إلى العجب. والذي صرفهم عن قبول الحق اعتقادهم الفاسد أن النار لا تمسّهم إلا أربعين يوماً، مدة عبادة أسلافهم العجل، وهي دعوى باطلة افتراها علماؤهم ليهوّنوا عليهم ارتكاب الجرائم، بل يُخلّدون في النار بكفرهم وظلمهم. ثم قال مستعظماً حالهم: فكيف إذا جمعناهم ليوم لا ريب فيه، وهو يوم القيامة، ووُفّيت كل نفس ما كسبت من خير أو شر وهم لا يُظلمون؟", "h": ["من الإعراض عن الدين والكفر به رفضُ التحاكم إليه.", "أفسد شيء للأديان بعقائدها وشرائعها وعباداتها: الافتراء فيها والابتداع عليها والقول فيها بغير علم.", "مضرّة الاغترار بما يذكره بعض الناس على الكتب الدينية من الحكايات والأباطيل بحجة الترغيب أو الترهيب، فيغترّ بها الناس فيضلّوا.", "فضيلة ذكر أهوال يوم القيامة وما يلاقيه فيها أهل الظلم والشر والفساد."], "k": "هل أطمئن نفسي بأماني تهوّن عليّ الذنب، كما اطمأنوا بـ«أياماً معدودات»؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 45;
insert into public.tdb_cards(topic, i, body) select 45, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٨ – ٢٠", "q": "شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلۡمَلَـٰٓئِكَةُ وَأُوْلُواْ ٱلۡعِلۡمِ قَآئِمَۢا بِٱلۡقِسۡطِۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿١٨﴾ إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ وَمَا ٱخۡتَلَفَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۗ وَمَن يَكۡفُرۡ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ﴿١٩﴾ فَإِنۡ حَآجُّوكَ فَقُلۡ أَسۡلَمۡتُ وَجۡهِيَ لِلَّهِ وَمَنِ ٱتَّبَعَنِۗ وَقُل لِّلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡأُمِّيِّـۧنَ ءَأَسۡلَمۡتُمۡۚ فَإِنۡ أَسۡلَمُواْ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ ﴿٢٠﴾", "w": [["شهد", "أخبر عن علم بحضوره الأمر المشهود به."], ["لا إله إلا هو", "لا معبود بحق في الأرض ولا في السماء إلا الله."], ["أولو العلم", "أصحاب العلم الصحيح المطابق للواقع، وهم الأنبياء والعلماء."], ["القسط", "العدل في الحكم والقول والعمل."], ["العزيز الحكيم", "الغالب ذو العزة التي لا تُغلب، الحكيم في كل خلقه وفعله وتصرفه."], ["الدين", "ما يُدان لله به، أي يُطاع فيه ويُخضع له به من الشرائع والعبادات."], ["الإسلام", "الانقياد لله بالطاعة والخلوص من الشرك، والمراد به هنا ملة الإسلام."], ["بغياً", "ظلماً وحسداً."], ["حاجّوك", "جادلوك وخاصموك بحجج باطلة."], ["أسلمت وجهي لله", "أخلصت أعمالي القلبية والبدنية لله وحده لا شريك له."], ["أوتوا الكتاب", "اليهود والنصارى."], ["الأميين", "العرب المشركين، سُمّوا بذلك لقلة من يقرأ ويكتب فيهم."], ["أأسلمتم", "استفهام المراد به الأمر: أسلِموا خيراً لكم."], ["وإن تولّوا", "أدبروا عن الحق بعد رؤيته، فلا يضرّك أمرهم إذ ما عليك إلا البلاغ."]], "m": "يخبر الله أنه شهد أنه لا إله إلا هو، وأن الملائكة وأولي العلم يشهدون كذلك شهادة علم وحق، وأنه قائم في الملكوت كله بالعدل، العزيز في ملكه، الحكيم في تدبيره؛ فردّ بهذه الشهادة باطل نصارى نجران ومكر اليهود وشرك العرب. ثم أخبر أن الدين الحق الذي لا يقبل ديناً سواه هو الإسلام، القائم على الانقياد الكامل لله والخلوص من الشرك. وأخبر أن اختلاف أهل الكتاب لم يكن عن جهل بالحق، وإنما عن علم، حملهم عليه البغي والحسد؛ إذ كل فرقة تريد الرئاسة الدينية والدنيوية لها دون غيرها، وبذلك يفسد أمر الدين والدنيا، وهذه سنة بشرية تورّط فيها المسلمون أيضاً بعد القرون المفضلة. ومن يكفر بآيات الله فإن الله سريع الحساب، يحصي عليه ذنوبه ويجزيه. ثم قال لرسوله: فإن حاجّك وفد نجران فاختصر الجدال معهم بإظهار موقفك: «أسلمت وجهي لله ومن اتبعن»، فليس فينا شيء لغير الله، ثم ادعُ أهل الكتاب والأميين إلى الإسلام؛ فإن أسلموا فقد اهتدوا، وإن تولّوا فلا يضرّك إعراضهم، إنما عليك البلاغ، والله بصير بالعباد.", "h": ["اعتبار الشهادة والأخذ بها إن كانت قائمة على العلم، وكان الشاهد أهلاً لذلك بأن كان مسلماً عدلاً.", "شهادة الله أعظم شهادة تثبت بها الشرائع والأحكام، وتليها شهادة الملائكة وأولي العلم.", "بطلان كل دين بعد الإسلام، وكل ملة غير ملته، لشهادة الله بذلك.", "الخلاف بين أهل العلم والدين يقع عندما يؤثرون الحياة الدنيا على الآخرة، فيتشوّفون إلى المناصب ويرغبون في الشرف، فيختلفون بغياً وحسداً.", "من أسلم قلبه وجوارحه لله، وأصبح وقفاً في حياته على الله، فقد اهتدى إلى سبيل النجاة والسلام.", "من علّق قلبه بالحياة الدنيا، وأعرض عما يصرفه عنها من العبادات، ضلّ في حياته وسعيه، وحسابه على الله."], "k": "«أسلمت وجهي لله»… هل في حياتي شيء أعطيه قلبي كله ولم أُسلمه بعدُ لله؟"}, {"lbl": "الآيتان ٢١ – ٢٢", "q": "إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ حَقّٖ وَيَقۡتُلُونَ ٱلَّذِينَ يَأۡمُرُونَ بِٱلۡقِسۡطِ مِنَ ٱلنَّاسِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ ﴿٢١﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِينَ ﴿٢٢﴾", "w": [["يكفرون", "يجحدون ويكذّبون."], ["النبيين", "جمع نبي، وهو ذكر من بني آدم أوحى الله إليه."], ["القسط", "العدل والحق والخير والمعروف."], ["فبشّرهم بعذاب أليم", "أخبرهم خبراً يظهر أثره على بشرة وجوههم ألماً وحسرة."], ["حبطت أعمالهم", "بطلت فلم ينتفعوا بها."], ["وما لهم من ناصرين", "لأن الله خذلهم وأراد إهلاكهم."]], "m": "ما زال السياق في هتك أستار الكفرة من أهل الكتابين، فذكر أن الذين يكفرون بآيات الله وحججه وما بعث به رسله، ويقتلون النبيين بغير حق، ويقتلون من يأمرونهم بالعدل من أتباع الأنبياء المؤمنين، هذه جرائم بعض أهل الكتاب، فبشّرهم بعذاب أليم. ثم أخبر أن أولئك حبطت أعمالهم في الدنيا، فلا يجنون منها عاقبة حسنة ولا ثناءً، والآخرة كذلك، وليس لهم من ناصرين يخلّصونهم من عذاب الله.", "h": ["الكفر والظلم من موجبات هلاك الدنيا ولزوم عذاب الآخرة.", "قتل الآمرين بالمعروف والناهين عن المنكر كقتل الأنبياء في عِظم الجرم.", "الشرك محبط للأعمال، مفسد لها في الدنيا والآخرة.", "من خذله الله لا ينصره أحد، ومن ينصره الله لا يغلبه أحد."], "k": "من يأمرني بالقسط وينصحني… هل أستقبل نصيحته بصدر رحب؟"}, {"lbl": "الآيات ٢٣ – ٢٥", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُدۡعَوۡنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحۡكُمَ بَيۡنَهُمۡ ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُمۡ وَهُم مُّعۡرِضُونَ ﴿٢٣﴾ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَٰتٖۖ وَغَرَّهُمۡ فِي دِينِهِم مَّا كَانُواْ يَفۡتَرُونَ ﴿٢٤﴾ فَكَيۡفَ إِذَا جَمَعۡنَٰهُمۡ لِيَوۡمٖ لَّا رَيۡبَ فِيهِ وَوُفِّيَتۡ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ ﴿٢٥﴾", "w": [["أوتوا نصيباً من الكتاب", "أُعطوا حظاً من التوراة."], ["يُدعون", "يُطلب منهم أن يتحاكموا فيما اختلفوا فيه إلى كتابهم الذي يؤمنون به، فيأبون ويعرضون."], ["يتولّى", "يرجع وهو مصمّم على عدم العودة إلى الحق."], ["أياماً معدودات", "قول اليهود، ويعنون أربعين يوماً، هي التي عبدوا فيها العجل بعد غياب موسى ﵇."], ["يفترون", "يكذبون."], ["ليوم لا ريب فيه", "يوم القيامة."], ["ما كسبت", "ما عملت من خير أو شر."], ["لا يُظلمون", "بأن يُعذّبوا بلا موجب من الشرك والكفر والمعاصي."]], "m": "ما زال السياق في فضح أهل الكتاب بذكر جرائمهم: ألم ينتهِ إلى علمك يا رسولنا أمر الذين أوتوا نصيباً من الكتاب، يُدعون إلى التحاكم إلى كتاب الله فيما اختلفوا فيه من صفاتك وشأن نبوتك، ثم يتولّى فريق منهم وهم مصمّمون على الإعراض؟ إنها حال تدعو إلى العجب. والذي صرفهم عن قبول الحق اعتقادهم الفاسد أن النار لا تمسّهم إلا أربعين يوماً، مدة عبادة أسلافهم العجل، وهي دعوى باطلة افتراها علماؤهم ليهوّنوا عليهم ارتكاب الجرائم، بل يُخلّدون في النار بكفرهم وظلمهم. ثم قال مستعظماً حالهم: فكيف إذا جمعناهم ليوم لا ريب فيه، وهو يوم القيامة، ووُفّيت كل نفس ما كسبت من خير أو شر وهم لا يُظلمون؟", "h": ["من الإعراض عن الدين والكفر به رفضُ التحاكم إليه.", "أفسد شيء للأديان بعقائدها وشرائعها وعباداتها: الافتراء فيها والابتداع عليها والقول فيها بغير علم.", "مضرّة الاغترار بما يذكره بعض الناس على الكتب الدينية من الحكايات والأباطيل بحجة الترغيب أو الترهيب، فيغترّ بها الناس فيضلّوا.", "فضيلة ذكر أهوال يوم القيامة وما يلاقيه فيها أهل الظلم والشر والفساد."], "k": "هل أطمئن نفسي بأماني تهوّن عليّ الذنب، كما اطمأنوا بـ«أياماً معدودات»؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (46, 3, 26, 32, 'سورة آل عمران ٢٦ – ٣٢', 'مالك الملك، وموالاة المؤمنين، وعلامة محبة الله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 46) = $j$[{"lbl": "الآيتان ٢٦ – ٢٧", "q": "قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٢٦﴾ تُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۖ وَتُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَتُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّۖ وَتَرۡزُقُ مَن تَشَآءُ بِغَيۡرِ حِسَابٖ ﴿٢٧﴾", "w": [["اللهمّ", "يا الله؛ حُذف حرف النداء وعُوّض عنه بالميم المشددة، وهو خاص بنداء الله."], ["مالك الملك", "الحاكم المتصرف يفعل في ملكه ما يشاء، والملك: ما سوى الله من سائر الكائنات."], ["تؤتي الملك", "تعطي السلطان والتصرف في بعض الملكوت."], ["تولج الليل في النهار", "تُدخل الليل في النهار، وتُدخل النهار في الليل."], ["تخرج الحيّ من الميت", "تُخرج حياً من ميت في المحسوسات كالدجاجة من البيضة، وفي المعنويات كالمؤمن من الكافر، والعكس."], ["بغير حساب", "بغير عدّ ولا حدّ لواسع فضله."]], "m": "من مناسبات نزول هاتين الآيتين أن الرسول ﷺ لما أخبر أصحابه أن ملك أمته سيبلغ كذا وكذا، سخر اليهود والمنافقون مستبعدين ذلك، فأنزل الله هاتين الآيتين ضمن الردّ على نصارى نجران، وأمره أن يقول: «اللهمّ مالك الملك تؤتي الملك من تشاء…»، ليعطيه ما وعده من اتساع ملك أمته حتى يشمل ملك فارس والروم، وليردّ على النصارى في تأليه عيسى ﵇؛ إذ المستحق للعبادة هو مالك الملك كله، يؤتي منه من يشاء وينزعه ممن يشاء، يُعزّ الذليل متى شاء ويُذلّ العزيز متى شاء، بيده الخير يفيضه على من يشاء، وهو على كل شيء قدير. يُدخل ساعات من الليل في النهار فيطول النهار، وساعات من النهار في الليل فيطول الليل، ويُخرج الإنسان من النطفة والنبتة من الحبة، والكافر من المؤمن والعكس؛ وهذه مظاهر ربوبيته المستلزمة لألوهيته. وبذلك تأكّد أمران: أن الله قادر على إعطاء رسوله ما وعده لأمته وقد فعل، وأن عيسى ﵇ لم يكن إلا عبداً مربوباً شرّفه الله بالرسالة وأيّده بالمعجزات.", "h": ["فضل الدعاء بهاتين الآيتين، بأن يقرأهما العبد ثم يقول: رحمن الدنيا والآخرة ورحيمهما، تعطي منهما من تشاء وتمنع من تشاء، اقضِ عني ديني؛ فإنه يُقضى بإذن الله، ويُعطى إن سأل حاجة من حوائج الدنيا والآخرة.", "استجابة الله لرسوله ﷺ، وإنجازه ما وعده في أمته.", "بطلان ألوهية عيسى ﵇، وثبوت عبوديته ورسالته وكرامته."], "k": "«بيدك الخير»… لمن أشكو حاجتي اليوم أولاً: للناس، أم لمالك الملك؟"}, {"lbl": "الآيات ٢٨ – ٣٠", "q": "لَّا يَتَّخِذِ ٱلۡمُؤۡمِنُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۖ وَمَن يَفۡعَلۡ ذَٰلِكَ فَلَيۡسَ مِنَ ٱللَّهِ فِي شَيۡءٍ إِلَّآ أَن تَتَّقُواْ مِنۡهُمۡ تُقَىٰةٗۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ ﴿٢٨﴾ قُلۡ إِن تُخۡفُواْ مَا فِي صُدُورِكُمۡ أَوۡ تُبۡدُوهُ يَعۡلَمۡهُ ٱللَّهُۗ وَيَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٢٩﴾ يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا وَمَا عَمِلَتۡ مِن سُوٓءٖ تَوَدُّ لَوۡ أَنَّ بَيۡنَهَا وَبَيۡنَهُۥٓ أَمَدَۢا بَعِيدٗاۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ ﴿٣٠﴾", "w": [["لا يتخذ", "لا يجعل."], ["أولياء", "جمع وليّ، يتولّونهم بالنصرة والمحبة والتأييد."], ["تُقاة", "وقاية باللسان، وهي الكلمة المُليّنة للجانب المبعدة للبغضاء."], ["محضراً", "حاضراً يوم القيامة."], ["أمداً بعيداً", "مدى وغاية بعيدة."], ["ويحذّركم الله نفسه", "يخوّفكم عقابه إن عصيتموه."]], "m": "ينهى الله المؤمنين عن اتخاذ الكافرين أولياء من دون المؤمنين، يبادلونهم المحبة والمناصرة على إخوانهم، وأعلمهم أن من يفعل ذلك فقد برئ الله منه، لكفره وردّته حيث والى أعداء الله وعادى أولياءه. ثم رخّص للمؤمنين المستضعفين الذين يعيشون تحت سلطان الكافرين أن يعطوهم حلاوة ألسنتهم دون قلوبهم وأعمالهم، فيتقون بذلك شرّهم بكلمة المصانعة والمجاملة: «إلا أن تتقوا منهم تقاة». ولخطر أمر الولاء والبراء قال: «ويحذّركم الله نفسه وإلى الله المصير».\nثم أمر رسوله أن يقول للناس: إن تخفوا ما في صدوركم من حب أو بغض، أو تُبدوه بقول أو عمل، يعلمه الله ويحاسب عليه، فليراقب العاقل ربه فلا يُقدم على معاصيه، وخاصة موالاة أعدائه على أوليائه. ثم ذكّرهم بيوم القيامة ليكفّوا عن الشر: يوم تجد كل نفس ما عملت من خير حاضراً تُجزى به، وما عملت من سوء حاضراً كذلك فتودّ لو أن بينها وبينه غاية بعيدة لا تُدرك. وأكّد التحذير: «ويحذّركم الله نفسه»، وختم بقوله «والله رؤوف بالعباد»، ونِعم ما ختم به؛ إذ لولاه لطارت قلوب العالمين فزعاً، فذو الرأفة بعباده لا يُيأس من رحمته.", "h": ["حرمة موالاة الكافرين مطلقاً.", "موالاة الكافرين على المؤمنين ردّة وكفر وبراءة من الله.", "جواز التقية في حال ضعف المؤمنين وقوة الكافرين.", "وجوب الحذر من عذاب الله، وذلك بطاعته.", "خطورة الموقف يوم القيامة، ووجوب الاستعداد له بالإيمان والتقوى."], "k": "يوم أجد ما عملت «محضراً»… أيّ عمل أتمنى أن أراه هناك، فأبدأ به اليوم؟"}, {"lbl": "الآيتان ٣١ – ٣٢", "q": "قُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِي يُحۡبِبۡكُمُ ٱللَّهُ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٣١﴾ قُلۡ أَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡكَٰفِرِينَ ﴿٣٢﴾", "w": [["تحبون الله", "لكمال ذاته وإنعامه عليكم."], ["يحببكم الله", "لطاعتكم إياه وطهارة أرواحكم بتقواه."], ["يغفر لكم ذنوبكم", "يسترها عليكم ولا يؤاخذكم بها."], ["فإن تولّوا", "أعرضوا عن الإيمان والطاعة."]], "m": "لما ادّعى وفد نصارى نجران أن تعظيمهم المسيح وأمه إنما هو طلب لحب الله، بحب ما يحب وتعظيم ما يعظّم، أمر الله رسوله أن يقول لهم: إن كنتم تحبون الله فاتّبعوني على ما جئت به من التوحيد والعبادة يحببكم الله ويغفر لكم ذنوبكم، والله غفور رحيم. فأبطل دعواهم، وأرشدهم إلى أمثل طريق للحصول على حب الله: متابعة الرسول ﷺ على ما جاء به من الإيمان والتوحيد والعبادة المزكّية للروح. ثم أمره أن يأمرهم وغيرهم من أهل الكتاب والمشركين بطاعة الله ورسوله، إذ هما طريق الكمال والإسعاد في الدنيا والآخرة، فإن أعرضوا فقد باؤوا بغضب الله لأنهم كافرون، والله لا يحب الكافرين.", "h": ["محبة العبد لربه واجبة، وهي من الإيمان.", "محبة الله للعبد هي غاية ما يسعى إليه أولو العلم في الحياة.", "طريق الحصول على محبة الله للعبد هو اتباع النبي محمد ﷺ بالإيمان بما جاء به واتباع شرعه وطاعته في المنشط والمكره؛ إذ ليس الشأن أن يُحِبّ العبد، وإنما الشأن أن يُحَبّ.", "دعوى محبة الله ورسوله مع مخالفة أمرهما ونهيهما دعوى باطلة، وصاحبها خاسر لا محالة."], "k": "أقول إني أحب الله… فما السنة التي أتبع فيها النبي ﷺ اليوم لتصدّق قولي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 46;
insert into public.tdb_cards(topic, i, body) select 46, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٢٦ – ٢٧", "q": "قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٢٦﴾ تُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۖ وَتُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَتُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّۖ وَتَرۡزُقُ مَن تَشَآءُ بِغَيۡرِ حِسَابٖ ﴿٢٧﴾", "w": [["اللهمّ", "يا الله؛ حُذف حرف النداء وعُوّض عنه بالميم المشددة، وهو خاص بنداء الله."], ["مالك الملك", "الحاكم المتصرف يفعل في ملكه ما يشاء، والملك: ما سوى الله من سائر الكائنات."], ["تؤتي الملك", "تعطي السلطان والتصرف في بعض الملكوت."], ["تولج الليل في النهار", "تُدخل الليل في النهار، وتُدخل النهار في الليل."], ["تخرج الحيّ من الميت", "تُخرج حياً من ميت في المحسوسات كالدجاجة من البيضة، وفي المعنويات كالمؤمن من الكافر، والعكس."], ["بغير حساب", "بغير عدّ ولا حدّ لواسع فضله."]], "m": "من مناسبات نزول هاتين الآيتين أن الرسول ﷺ لما أخبر أصحابه أن ملك أمته سيبلغ كذا وكذا، سخر اليهود والمنافقون مستبعدين ذلك، فأنزل الله هاتين الآيتين ضمن الردّ على نصارى نجران، وأمره أن يقول: «اللهمّ مالك الملك تؤتي الملك من تشاء…»، ليعطيه ما وعده من اتساع ملك أمته حتى يشمل ملك فارس والروم، وليردّ على النصارى في تأليه عيسى ﵇؛ إذ المستحق للعبادة هو مالك الملك كله، يؤتي منه من يشاء وينزعه ممن يشاء، يُعزّ الذليل متى شاء ويُذلّ العزيز متى شاء، بيده الخير يفيضه على من يشاء، وهو على كل شيء قدير. يُدخل ساعات من الليل في النهار فيطول النهار، وساعات من النهار في الليل فيطول الليل، ويُخرج الإنسان من النطفة والنبتة من الحبة، والكافر من المؤمن والعكس؛ وهذه مظاهر ربوبيته المستلزمة لألوهيته. وبذلك تأكّد أمران: أن الله قادر على إعطاء رسوله ما وعده لأمته وقد فعل، وأن عيسى ﵇ لم يكن إلا عبداً مربوباً شرّفه الله بالرسالة وأيّده بالمعجزات.", "h": ["فضل الدعاء بهاتين الآيتين، بأن يقرأهما العبد ثم يقول: رحمن الدنيا والآخرة ورحيمهما، تعطي منهما من تشاء وتمنع من تشاء، اقضِ عني ديني؛ فإنه يُقضى بإذن الله، ويُعطى إن سأل حاجة من حوائج الدنيا والآخرة.", "استجابة الله لرسوله ﷺ، وإنجازه ما وعده في أمته.", "بطلان ألوهية عيسى ﵇، وثبوت عبوديته ورسالته وكرامته."], "k": "«بيدك الخير»… لمن أشكو حاجتي اليوم أولاً: للناس، أم لمالك الملك؟"}, {"lbl": "الآيات ٢٨ – ٣٠", "q": "لَّا يَتَّخِذِ ٱلۡمُؤۡمِنُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۖ وَمَن يَفۡعَلۡ ذَٰلِكَ فَلَيۡسَ مِنَ ٱللَّهِ فِي شَيۡءٍ إِلَّآ أَن تَتَّقُواْ مِنۡهُمۡ تُقَىٰةٗۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ ﴿٢٨﴾ قُلۡ إِن تُخۡفُواْ مَا فِي صُدُورِكُمۡ أَوۡ تُبۡدُوهُ يَعۡلَمۡهُ ٱللَّهُۗ وَيَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٢٩﴾ يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا وَمَا عَمِلَتۡ مِن سُوٓءٖ تَوَدُّ لَوۡ أَنَّ بَيۡنَهَا وَبَيۡنَهُۥٓ أَمَدَۢا بَعِيدٗاۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ ﴿٣٠﴾", "w": [["لا يتخذ", "لا يجعل."], ["أولياء", "جمع وليّ، يتولّونهم بالنصرة والمحبة والتأييد."], ["تُقاة", "وقاية باللسان، وهي الكلمة المُليّنة للجانب المبعدة للبغضاء."], ["محضراً", "حاضراً يوم القيامة."], ["أمداً بعيداً", "مدى وغاية بعيدة."], ["ويحذّركم الله نفسه", "يخوّفكم عقابه إن عصيتموه."]], "m": "ينهى الله المؤمنين عن اتخاذ الكافرين أولياء من دون المؤمنين، يبادلونهم المحبة والمناصرة على إخوانهم، وأعلمهم أن من يفعل ذلك فقد برئ الله منه، لكفره وردّته حيث والى أعداء الله وعادى أولياءه. ثم رخّص للمؤمنين المستضعفين الذين يعيشون تحت سلطان الكافرين أن يعطوهم حلاوة ألسنتهم دون قلوبهم وأعمالهم، فيتقون بذلك شرّهم بكلمة المصانعة والمجاملة: «إلا أن تتقوا منهم تقاة». ولخطر أمر الولاء والبراء قال: «ويحذّركم الله نفسه وإلى الله المصير».\nثم أمر رسوله أن يقول للناس: إن تخفوا ما في صدوركم من حب أو بغض، أو تُبدوه بقول أو عمل، يعلمه الله ويحاسب عليه، فليراقب العاقل ربه فلا يُقدم على معاصيه، وخاصة موالاة أعدائه على أوليائه. ثم ذكّرهم بيوم القيامة ليكفّوا عن الشر: يوم تجد كل نفس ما عملت من خير حاضراً تُجزى به، وما عملت من سوء حاضراً كذلك فتودّ لو أن بينها وبينه غاية بعيدة لا تُدرك. وأكّد التحذير: «ويحذّركم الله نفسه»، وختم بقوله «والله رؤوف بالعباد»، ونِعم ما ختم به؛ إذ لولاه لطارت قلوب العالمين فزعاً، فذو الرأفة بعباده لا يُيأس من رحمته.", "h": ["حرمة موالاة الكافرين مطلقاً.", "موالاة الكافرين على المؤمنين ردّة وكفر وبراءة من الله.", "جواز التقية في حال ضعف المؤمنين وقوة الكافرين.", "وجوب الحذر من عذاب الله، وذلك بطاعته.", "خطورة الموقف يوم القيامة، ووجوب الاستعداد له بالإيمان والتقوى."], "k": "يوم أجد ما عملت «محضراً»… أيّ عمل أتمنى أن أراه هناك، فأبدأ به اليوم؟"}, {"lbl": "الآيتان ٣١ – ٣٢", "q": "قُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِي يُحۡبِبۡكُمُ ٱللَّهُ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٣١﴾ قُلۡ أَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡكَٰفِرِينَ ﴿٣٢﴾", "w": [["تحبون الله", "لكمال ذاته وإنعامه عليكم."], ["يحببكم الله", "لطاعتكم إياه وطهارة أرواحكم بتقواه."], ["يغفر لكم ذنوبكم", "يسترها عليكم ولا يؤاخذكم بها."], ["فإن تولّوا", "أعرضوا عن الإيمان والطاعة."]], "m": "لما ادّعى وفد نصارى نجران أن تعظيمهم المسيح وأمه إنما هو طلب لحب الله، بحب ما يحب وتعظيم ما يعظّم، أمر الله رسوله أن يقول لهم: إن كنتم تحبون الله فاتّبعوني على ما جئت به من التوحيد والعبادة يحببكم الله ويغفر لكم ذنوبكم، والله غفور رحيم. فأبطل دعواهم، وأرشدهم إلى أمثل طريق للحصول على حب الله: متابعة الرسول ﷺ على ما جاء به من الإيمان والتوحيد والعبادة المزكّية للروح. ثم أمره أن يأمرهم وغيرهم من أهل الكتاب والمشركين بطاعة الله ورسوله، إذ هما طريق الكمال والإسعاد في الدنيا والآخرة، فإن أعرضوا فقد باؤوا بغضب الله لأنهم كافرون، والله لا يحب الكافرين.", "h": ["محبة العبد لربه واجبة، وهي من الإيمان.", "محبة الله للعبد هي غاية ما يسعى إليه أولو العلم في الحياة.", "طريق الحصول على محبة الله للعبد هو اتباع النبي محمد ﷺ بالإيمان بما جاء به واتباع شرعه وطاعته في المنشط والمكره؛ إذ ليس الشأن أن يُحِبّ العبد، وإنما الشأن أن يُحَبّ.", "دعوى محبة الله ورسوله مع مخالفة أمرهما ونهيهما دعوى باطلة، وصاحبها خاسر لا محالة."], "k": "أقول إني أحب الله… فما السنة التي أتبع فيها النبي ﷺ اليوم لتصدّق قولي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (47, 3, 33, 44, 'سورة آل عمران ٣٣ – ٤٤', 'آل عمران: امرأة عمران ومريم وزكريا', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 47) = $j$[{"lbl": "الآيات ٣٣ – ٣٧", "q": "۞إِنَّ ٱللَّهَ ٱصۡطَفَىٰٓ ءَادَمَ وَنُوحٗا وَءَالَ إِبۡرَٰهِيمَ وَءَالَ عِمۡرَٰنَ عَلَى ٱلۡعَٰلَمِينَ ﴿٣٣﴾ ذُرِّيَّةَۢ بَعۡضُهَا مِنۢ بَعۡضٖۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ﴿٣٤﴾ إِذۡ قَالَتِ ٱمۡرَأَتُ عِمۡرَٰنَ رَبِّ إِنِّي نَذَرۡتُ لَكَ مَا فِي بَطۡنِي مُحَرَّرٗا فَتَقَبَّلۡ مِنِّيٓۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٣٥﴾ فَلَمَّا وَضَعَتۡهَا قَالَتۡ رَبِّ إِنِّي وَضَعۡتُهَآ أُنثَىٰ وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ وَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّي سَمَّيۡتُهَا مَرۡيَمَ وَإِنِّيٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ ﴿٣٦﴾ فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٖ وَأَنۢبَتَهَا نَبَاتًا حَسَنٗا وَكَفَّلَهَا زَكَرِيَّاۖ كُلَّمَا دَخَلَ عَلَيۡهَا زَكَرِيَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقٗاۖ قَالَ يَٰمَرۡيَمُ أَنَّىٰ لَكِ هَٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ ﴿٣٧﴾", "w": [["اصطفى آدم", "اختار آدم أبا البشر ﵇."], ["آل إبراهيم", "آل الرجل: أهله وأتباعه على دينه الحق."], ["عمران", "رجل صالح من صلحاء بني إسرائيل، زوج حنّة وأبو مريم."], ["العالمين", "الناس المعاصرين لهم."], ["نذرت لك ما في بطني", "ألزمت نفسها أن تجعله لله يعبده ويخدم بيته، وهو بيت المقدس."], ["محرّراً", "خالصاً لله لا شركة فيه لأحد، فلا تنتفع به أبداً."], ["مريم", "خادمة الرب."], ["أعيذها بك", "أحصّنها وأحفظها بجنابك من الشيطان."], ["وكفّلها زكريا", "زكريا أبو يحيى ﵉، وكانت امرأته أختاً لحنّة."], ["المحراب", "مقصورة ملاصقة للمسجد."], ["أنّى لك هذا", "من أين جاءك هذا؟"]], "m": "لما ادّعى نصارى نجران ما ادّعوه في تأليه المسيح وأمه، أنزل الله هذه الآيات يبيّن فيها مبدأ أمرهما وحقيقته: أخبر أنه اصطفى آدم ونوحاً وآل إبراهيم وآل عمران لدينه وعبادته، ففضّلهم على الناس، ذرية بعضها من بعض في العقائد والكمالات الروحية، والله سميع لقول امرأة عمران، عليم بحالها. وذلك أنها كانت لا تلد، فرأت طائراً يطعم أفراخه فحنّت إلى الولد، وسألت ربها أن يرزقها ولداً تجعله له يعبده ويخدم بيته، فحملت، ومات زوجها وهي حبلى، فقالت: «رب إني نذرت لك ما في بطني محرّراً فتقبّل مني». فلما وضعتها أنثى تحسّرت، لأن الذكر ليس كالأنثى في الخدمة في بيت المقدس، وسمّتها مريم، وسألت ربها أن يحفظها وذريتها من الشيطان الرجيم، فاستجاب لها. وتقبّلها ربها وأنبتها نباتاً حسناً عجيباً، وبعثت بها أمها إلى صلحاء بني إسرائيل لأنها نذرتها لله، فأحب كلٌّ أن يكفلها، فكفلها زكريا فنشأت في بيت خالتها. ولما كبرت أدخلها المحراب لتتعبّد، فكان كلما دخل عليها وجد عندها فاكهة الصيف في الشتاء وفاكهة الشتاء في الصيف، فيقول: يا مريم أنّى لك هذا؟ فتقول: هو من عند الله، إن الله يرزق من يشاء بغير حساب.", "h": ["بيان إفضال الله وإنعامه على من يشاء.", "بيان أن عيسى ﵇ ليس ابن الله ولا هو الله ولا ثالث ثلاثة، بل هو عبد الله ورسوله، من بيت شرف وصلاح في بني إسرائيل.", "استجابة الله لدعاء أوليائه، كما استجاب لحنّة ورزقها الولد وأعاذ بنتها وولدها من الشيطان الرجيم.", "مشروعية النذر لله، وهو التزام المؤمن الطاعة تقرباً إلى الله.", "بيان فضل الذكر على الأنثى في باب النهوض بالأعمال والواجبات.", "جواز التحسّر والتأسف لما يفوت العبد من الخير الذي كان يأمله.", "ثبوت كرامات الأولياء، كما تمّ لمريم في محرابها."], "k": "«إن الله يرزق من يشاء بغير حساب»… هل أقيس رزقي بالأسباب وحدها، وأنسى باب «من عند الله»؟"}, {"lbl": "الآيات ٣٨ – ٤١", "q": "هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ ﴿٣٨﴾ فَنَادَتۡهُ ٱلۡمَلَـٰٓئِكَةُ وَهُوَ قَآئِمٞ يُصَلِّي فِي ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحۡيَىٰ مُصَدِّقَۢا بِكَلِمَةٖ مِّنَ ٱللَّهِ وَسَيِّدٗا وَحَصُورٗا وَنَبِيّٗا مِّنَ ٱلصَّـٰلِحِينَ ﴿٣٩﴾ قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَقَدۡ بَلَغَنِيَ ٱلۡكِبَرُ وَٱمۡرَأَتِي عَاقِرٞۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفۡعَلُ مَا يَشَآءُ ﴿٤٠﴾ قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمۡزٗاۗ وَٱذۡكُر رَّبَّكَ كَثِيرٗا وَسَبِّحۡ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ ﴿٤١﴾", "w": [["هنالك", "ثَمّ، عندما رأى كرامة الله لمريم."], ["سيّداً", "شريفاً ذا علم وحلم."], ["وحصوراً", "لا رغبة له في النساء."], ["غلام", "ولد ذكر."], ["عاقر", "عقيم لا تلد."], ["آية", "علامة يستدل بها على بداية الحمل ليشكر النعمة."], ["إلا رمزاً", "إلا إشارة بالرأس أو باليد يُفهم منها ما يُفهم من الكلام."], ["الإبكار والعشيّ", "الإبكار: أول النهار، والعشي: آخره."]], "m": "لما شاهد زكريا من كرامات الله لمريم أنها تؤتى بفاكهة الصيف في الشتاء وفاكهة الشتاء في الصيف، تذكّر أن الله قد يعطي ما يشاء لمن يشاء على غير المعتاد من السنن، وأن كبر سنّه وعقم امرأته لا يمنعان أن يعطيه الله ولداً، فسأل ربه الولد، فاستجاب له، فبشّرته الملائكة وهو قائم يصلي في المحراب بولد اسمه يحيى، مصدّقاً بكلمة من الله، وهو عيسى ﵇ الذي كان بقول الله له: كن، فكان. ووصفه بأنه سيّد ذو علم وحلم، وحصور، ونبي من الصالحين. ثم أراد زكريا أن يتثبّت من الخبر فقال: «رب أنّى يكون لي غلام وقد بلغني الكبر وامرأتي عاقر؟» فأُجيب: كذلك الله يفعل ما يشاء. فقال: رب اجعل لي علامة أستدل بها على الحمل لأستقبل النعمة بالشكر، فقال: آيتك ألا تقدر على كلام الناس ثلاثة أيام إلا بالإشارة، وأمره أن يقابل هذا الإنعام بالشكر: «واذكر ربك كثيراً وسبّح بالعشيّ والإبكار».", "h": ["الاعتبار بالغير؛ إذ زكريا دعا بالولد لما رأى كرامة الله لمريم.", "مشروعية الدعاء، وكونه سرّاً أقرب إلى الإجابة، وكونه في الصلاة كذلك.", "جواز تلبيس إبليس على المؤمن، ولكن الله يُذهب كيده ووسوسته.", "جواز سؤال الولد الصالح.", "كرامات الله لأوليائه باستجابة دعائهم.", "فضل الإكثار من الذكر، وفضيلة صلاتي الصبح والعصر."], "k": "زكريا ﵇ رأى نعمة الله على غيره فدعا لنفسه… هل تحرّك نِعم الله على الناس دعائي، أم تحرّك حسدي؟"}, {"lbl": "الآيات ٤٢ – ٤٤", "q": "وَإِذۡ قَالَتِ ٱلۡمَلَـٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ ٱصۡطَفَىٰكِ وَطَهَّرَكِ وَٱصۡطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلۡعَٰلَمِينَ ﴿٤٢﴾ يَٰمَرۡيَمُ ٱقۡنُتِي لِرَبِّكِ وَٱسۡجُدِي وَٱرۡكَعِي مَعَ ٱلرَّـٰكِعِينَ ﴿٤٣﴾ ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۚ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يُلۡقُونَ أَقۡلَٰمَهُمۡ أَيُّهُمۡ يَكۡفُلُ مَرۡيَمَ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يَخۡتَصِمُونَ ﴿٤٤﴾", "w": [["وإذ قالت الملائكة", "اذكر لوفد نجران ما قالت الملائكة، فإنه دليل على صدق نبوتك."], ["اصطفاك", "اختارك لعبادته وحسن طاعته."], ["وطهّرك", "من الذنوب وسائر النقائص المخلّة بالولاية لله."], ["على نساء العالمين", "فضّلك على نساء عالمك بما أهّلك له من ولادة عيسى ﵇ من غير أب."], ["اقنتي", "أطيعي ربك واخشعي له."], ["واركعي مع الراكعين", "اشهدي صلاة الجماعة في بيت المقدس."], ["من أنباء الغيب", "من أخبار الغيب."], ["يلقون أقلامهم", "يقترعون بأقلامهم على كفالة مريم."], ["يختصمون", "في شأن كفالة مريم."]], "m": "يقول الله لنبيه: اذكر لوفد نجران الذين يحاجّونك في ألوهية المسيح إذ قالت الملائكة لمريم أم المسيح: إن الله اختارك وطهّرك من الذنوب والنقائص، وفضّلك على نساء عالمك حين أظهر فيك آية قدرته فولدتِ عيسى بكلمة الله على غير سنّته في تناسل البشر، وأمرها بمواصلة الطاعة والخشوع: «يا مريم اقنتي لربك واسجدي واركعي مع الراكعين»، وخصّ الصلاة بالذكر لأهميتها. ثم خاطب رسوله ﷺ بأن هذا القصص كله عن حنّة ومريم وزكريا ويحيى من أنباء الغيب يوحيه إليه، فهو بذلك نبيه ورسوله، وما جاء به هو الحق. وما كنتَ عندهم إذ يقترعون بأقلامهم على من يكفل مريم، فوقف قلم زكريا ففاز بكفالتها. وبهذا قامت الحجة على أهل الكتاب بأنه لا إله إلا الله، وأن محمداً رسول الله، وأن الدين الحق هو الإسلام.", "h": ["فضل مريم، وأنها وليّة صدّيقة، وقد أخبر النبي ﷺ أنها من كُمّل النساء.", "أهل القرب من الله هم أهل طاعته القانتون له.", "مشروعية الاقتراع عند الاختلاف، وهو وإن كان في شرع من قبلنا فإنه مقرَّر في شرعنا."], "k": "«اقنتي لربك واسجدي واركعي»… كيف أجعل صلاتي اليوم أطول خشوعاً ولو بركعتين؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 47;
insert into public.tdb_cards(topic, i, body) select 47, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٣ – ٣٧", "q": "۞إِنَّ ٱللَّهَ ٱصۡطَفَىٰٓ ءَادَمَ وَنُوحٗا وَءَالَ إِبۡرَٰهِيمَ وَءَالَ عِمۡرَٰنَ عَلَى ٱلۡعَٰلَمِينَ ﴿٣٣﴾ ذُرِّيَّةَۢ بَعۡضُهَا مِنۢ بَعۡضٖۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ﴿٣٤﴾ إِذۡ قَالَتِ ٱمۡرَأَتُ عِمۡرَٰنَ رَبِّ إِنِّي نَذَرۡتُ لَكَ مَا فِي بَطۡنِي مُحَرَّرٗا فَتَقَبَّلۡ مِنِّيٓۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٣٥﴾ فَلَمَّا وَضَعَتۡهَا قَالَتۡ رَبِّ إِنِّي وَضَعۡتُهَآ أُنثَىٰ وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ وَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّي سَمَّيۡتُهَا مَرۡيَمَ وَإِنِّيٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ ﴿٣٦﴾ فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٖ وَأَنۢبَتَهَا نَبَاتًا حَسَنٗا وَكَفَّلَهَا زَكَرِيَّاۖ كُلَّمَا دَخَلَ عَلَيۡهَا زَكَرِيَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقٗاۖ قَالَ يَٰمَرۡيَمُ أَنَّىٰ لَكِ هَٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ ﴿٣٧﴾", "w": [["اصطفى آدم", "اختار آدم أبا البشر ﵇."], ["آل إبراهيم", "آل الرجل: أهله وأتباعه على دينه الحق."], ["عمران", "رجل صالح من صلحاء بني إسرائيل، زوج حنّة وأبو مريم."], ["العالمين", "الناس المعاصرين لهم."], ["نذرت لك ما في بطني", "ألزمت نفسها أن تجعله لله يعبده ويخدم بيته، وهو بيت المقدس."], ["محرّراً", "خالصاً لله لا شركة فيه لأحد، فلا تنتفع به أبداً."], ["مريم", "خادمة الرب."], ["أعيذها بك", "أحصّنها وأحفظها بجنابك من الشيطان."], ["وكفّلها زكريا", "زكريا أبو يحيى ﵉، وكانت امرأته أختاً لحنّة."], ["المحراب", "مقصورة ملاصقة للمسجد."], ["أنّى لك هذا", "من أين جاءك هذا؟"]], "m": "لما ادّعى نصارى نجران ما ادّعوه في تأليه المسيح وأمه، أنزل الله هذه الآيات يبيّن فيها مبدأ أمرهما وحقيقته: أخبر أنه اصطفى آدم ونوحاً وآل إبراهيم وآل عمران لدينه وعبادته، ففضّلهم على الناس، ذرية بعضها من بعض في العقائد والكمالات الروحية، والله سميع لقول امرأة عمران، عليم بحالها. وذلك أنها كانت لا تلد، فرأت طائراً يطعم أفراخه فحنّت إلى الولد، وسألت ربها أن يرزقها ولداً تجعله له يعبده ويخدم بيته، فحملت، ومات زوجها وهي حبلى، فقالت: «رب إني نذرت لك ما في بطني محرّراً فتقبّل مني». فلما وضعتها أنثى تحسّرت، لأن الذكر ليس كالأنثى في الخدمة في بيت المقدس، وسمّتها مريم، وسألت ربها أن يحفظها وذريتها من الشيطان الرجيم، فاستجاب لها. وتقبّلها ربها وأنبتها نباتاً حسناً عجيباً، وبعثت بها أمها إلى صلحاء بني إسرائيل لأنها نذرتها لله، فأحب كلٌّ أن يكفلها، فكفلها زكريا فنشأت في بيت خالتها. ولما كبرت أدخلها المحراب لتتعبّد، فكان كلما دخل عليها وجد عندها فاكهة الصيف في الشتاء وفاكهة الشتاء في الصيف، فيقول: يا مريم أنّى لك هذا؟ فتقول: هو من عند الله، إن الله يرزق من يشاء بغير حساب.", "h": ["بيان إفضال الله وإنعامه على من يشاء.", "بيان أن عيسى ﵇ ليس ابن الله ولا هو الله ولا ثالث ثلاثة، بل هو عبد الله ورسوله، من بيت شرف وصلاح في بني إسرائيل.", "استجابة الله لدعاء أوليائه، كما استجاب لحنّة ورزقها الولد وأعاذ بنتها وولدها من الشيطان الرجيم.", "مشروعية النذر لله، وهو التزام المؤمن الطاعة تقرباً إلى الله.", "بيان فضل الذكر على الأنثى في باب النهوض بالأعمال والواجبات.", "جواز التحسّر والتأسف لما يفوت العبد من الخير الذي كان يأمله.", "ثبوت كرامات الأولياء، كما تمّ لمريم في محرابها."], "k": "«إن الله يرزق من يشاء بغير حساب»… هل أقيس رزقي بالأسباب وحدها، وأنسى باب «من عند الله»؟"}, {"lbl": "الآيات ٣٨ – ٤١", "q": "هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ ﴿٣٨﴾ فَنَادَتۡهُ ٱلۡمَلَـٰٓئِكَةُ وَهُوَ قَآئِمٞ يُصَلِّي فِي ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحۡيَىٰ مُصَدِّقَۢا بِكَلِمَةٖ مِّنَ ٱللَّهِ وَسَيِّدٗا وَحَصُورٗا وَنَبِيّٗا مِّنَ ٱلصَّـٰلِحِينَ ﴿٣٩﴾ قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَقَدۡ بَلَغَنِيَ ٱلۡكِبَرُ وَٱمۡرَأَتِي عَاقِرٞۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفۡعَلُ مَا يَشَآءُ ﴿٤٠﴾ قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمۡزٗاۗ وَٱذۡكُر رَّبَّكَ كَثِيرٗا وَسَبِّحۡ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ ﴿٤١﴾", "w": [["هنالك", "ثَمّ، عندما رأى كرامة الله لمريم."], ["سيّداً", "شريفاً ذا علم وحلم."], ["وحصوراً", "لا رغبة له في النساء."], ["غلام", "ولد ذكر."], ["عاقر", "عقيم لا تلد."], ["آية", "علامة يستدل بها على بداية الحمل ليشكر النعمة."], ["إلا رمزاً", "إلا إشارة بالرأس أو باليد يُفهم منها ما يُفهم من الكلام."], ["الإبكار والعشيّ", "الإبكار: أول النهار، والعشي: آخره."]], "m": "لما شاهد زكريا من كرامات الله لمريم أنها تؤتى بفاكهة الصيف في الشتاء وفاكهة الشتاء في الصيف، تذكّر أن الله قد يعطي ما يشاء لمن يشاء على غير المعتاد من السنن، وأن كبر سنّه وعقم امرأته لا يمنعان أن يعطيه الله ولداً، فسأل ربه الولد، فاستجاب له، فبشّرته الملائكة وهو قائم يصلي في المحراب بولد اسمه يحيى، مصدّقاً بكلمة من الله، وهو عيسى ﵇ الذي كان بقول الله له: كن، فكان. ووصفه بأنه سيّد ذو علم وحلم، وحصور، ونبي من الصالحين. ثم أراد زكريا أن يتثبّت من الخبر فقال: «رب أنّى يكون لي غلام وقد بلغني الكبر وامرأتي عاقر؟» فأُجيب: كذلك الله يفعل ما يشاء. فقال: رب اجعل لي علامة أستدل بها على الحمل لأستقبل النعمة بالشكر، فقال: آيتك ألا تقدر على كلام الناس ثلاثة أيام إلا بالإشارة، وأمره أن يقابل هذا الإنعام بالشكر: «واذكر ربك كثيراً وسبّح بالعشيّ والإبكار».", "h": ["الاعتبار بالغير؛ إذ زكريا دعا بالولد لما رأى كرامة الله لمريم.", "مشروعية الدعاء، وكونه سرّاً أقرب إلى الإجابة، وكونه في الصلاة كذلك.", "جواز تلبيس إبليس على المؤمن، ولكن الله يُذهب كيده ووسوسته.", "جواز سؤال الولد الصالح.", "كرامات الله لأوليائه باستجابة دعائهم.", "فضل الإكثار من الذكر، وفضيلة صلاتي الصبح والعصر."], "k": "زكريا ﵇ رأى نعمة الله على غيره فدعا لنفسه… هل تحرّك نِعم الله على الناس دعائي، أم تحرّك حسدي؟"}, {"lbl": "الآيات ٤٢ – ٤٤", "q": "وَإِذۡ قَالَتِ ٱلۡمَلَـٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ ٱصۡطَفَىٰكِ وَطَهَّرَكِ وَٱصۡطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلۡعَٰلَمِينَ ﴿٤٢﴾ يَٰمَرۡيَمُ ٱقۡنُتِي لِرَبِّكِ وَٱسۡجُدِي وَٱرۡكَعِي مَعَ ٱلرَّـٰكِعِينَ ﴿٤٣﴾ ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۚ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يُلۡقُونَ أَقۡلَٰمَهُمۡ أَيُّهُمۡ يَكۡفُلُ مَرۡيَمَ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يَخۡتَصِمُونَ ﴿٤٤﴾", "w": [["وإذ قالت الملائكة", "اذكر لوفد نجران ما قالت الملائكة، فإنه دليل على صدق نبوتك."], ["اصطفاك", "اختارك لعبادته وحسن طاعته."], ["وطهّرك", "من الذنوب وسائر النقائص المخلّة بالولاية لله."], ["على نساء العالمين", "فضّلك على نساء عالمك بما أهّلك له من ولادة عيسى ﵇ من غير أب."], ["اقنتي", "أطيعي ربك واخشعي له."], ["واركعي مع الراكعين", "اشهدي صلاة الجماعة في بيت المقدس."], ["من أنباء الغيب", "من أخبار الغيب."], ["يلقون أقلامهم", "يقترعون بأقلامهم على كفالة مريم."], ["يختصمون", "في شأن كفالة مريم."]], "m": "يقول الله لنبيه: اذكر لوفد نجران الذين يحاجّونك في ألوهية المسيح إذ قالت الملائكة لمريم أم المسيح: إن الله اختارك وطهّرك من الذنوب والنقائص، وفضّلك على نساء عالمك حين أظهر فيك آية قدرته فولدتِ عيسى بكلمة الله على غير سنّته في تناسل البشر، وأمرها بمواصلة الطاعة والخشوع: «يا مريم اقنتي لربك واسجدي واركعي مع الراكعين»، وخصّ الصلاة بالذكر لأهميتها. ثم خاطب رسوله ﷺ بأن هذا القصص كله عن حنّة ومريم وزكريا ويحيى من أنباء الغيب يوحيه إليه، فهو بذلك نبيه ورسوله، وما جاء به هو الحق. وما كنتَ عندهم إذ يقترعون بأقلامهم على من يكفل مريم، فوقف قلم زكريا ففاز بكفالتها. وبهذا قامت الحجة على أهل الكتاب بأنه لا إله إلا الله، وأن محمداً رسول الله، وأن الدين الحق هو الإسلام.", "h": ["فضل مريم، وأنها وليّة صدّيقة، وقد أخبر النبي ﷺ أنها من كُمّل النساء.", "أهل القرب من الله هم أهل طاعته القانتون له.", "مشروعية الاقتراع عند الاختلاف، وهو وإن كان في شرع من قبلنا فإنه مقرَّر في شرعنا."], "k": "«اقنتي لربك واسجدي واركعي»… كيف أجعل صلاتي اليوم أطول خشوعاً ولو بركعتين؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (48, 3, 45, 58, 'سورة آل عمران ٤٥ – ٥٨', 'عيسى ﵇: البشارة به، ومعجزاته، ورفعه', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 48) = $j$[{"lbl": "الآيات ٤٥ – ٤٧", "q": "إِذۡ قَالَتِ ٱلۡمَلَـٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٖ مِّنۡهُ ٱسۡمُهُ ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ وَجِيهٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمِنَ ٱلۡمُقَرَّبِينَ ﴿٤٥﴾ وَيُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗا وَمِنَ ٱلصَّـٰلِحِينَ ﴿٤٦﴾ قَالَتۡ رَبِّ أَنَّىٰ يَكُونُ لِي وَلَدٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخۡلُقُ مَا يَشَآءُۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ ﴿٤٧﴾", "w": [["يبشّرك", "يخبرك بخبر سارّ مفرح."], ["بكلمة منه", "هو المسيح ﵇، وسُمّي كلمة لأنه كان بكلمة الله: كن."], ["المسيح", "لقب عيسى ﵇، ومن معانيه: الصدّيق."], ["وجيهاً", "ذا جاه وقدر وشرف بين الناس."], ["وكهلاً", "الكهولة: سنّ ما بين الشباب والشيخوخة."], ["ولم يمسسني بشر", "لم يقربني رجل."], ["قضى أمراً", "أراده وحكم بوجوده."]], "m": "ما زال السياق في حِجاج وفد نصارى نجران: واذكر لهم إذ قالت الملائكة يا مريم إن الله يبشّرك بكلمة منه، إذ أخبرها جبريل ﵇ بأن الله يبشّرها بولد يكون بكلمة الله، اسمه المسيح عيسى ابن مريم، ذو جاه وشرف في الدنيا والآخرة ومن المقربين، يكلّم الناس في مهده وقت رضاعه كما يكلمهم في كهولته، ومن الصالحين الذين يؤدّون حقوق الله وحقوق عباده. فقالت مريم: رب أنّى يكون لي ولد ولم يمسسني بشر، وسنّتك في خلق الولد الاتصال؟ فأجابها جبريل: الأمر كذلك، سيخلق الله منك ولداً من غير أب، وهو يخلق ما يشاء، إذا قضى أمراً فإنما يقول له كن فيكون.", "h": ["بيان شرف مريم وكرامتها على ربها، إذ كلّمها جبريل وبشّرها بعد أن تمثّل لها بشراً.", "بيان شرف عيسى ﵇ ووجاهته في الدنيا والآخرة، وأنه من المقربين والصالحين.", "تكلّم عيسى ﵇ في المهد آية من آيات الله؛ إذ لم تجرِ العادة أن يتكلم الرضيع في مهده.", "جواز طلب الاستفسار عما يكون مخالفاً للعادة لمعرفة سرّه أو علّته أو حكمته."], "k": "«إذا قضى أمراً فإنما يقول له كن فيكون»… ما الأمر الذي أظنه مستحيلاً وأحتاج أن أتذكّر معه هذه الآية؟"}, {"lbl": "الآيات ٤٨ – ٥١", "q": "وَيُعَلِّمُهُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ ﴿٤٨﴾ وَرَسُولًا إِلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ أَنِّي قَدۡ جِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ أَنِّيٓ أَخۡلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيۡرَۢا بِإِذۡنِ ٱللَّهِۖ وَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ وَأُحۡيِ ٱلۡمَوۡتَىٰ بِإِذۡنِ ٱللَّهِۖ وَأُنَبِّئُكُم بِمَا تَأۡكُلُونَ وَمَا تَدَّخِرُونَ فِي بُيُوتِكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ ﴿٤٩﴾ وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡۚ وَجِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿٥٠﴾ إِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ﴿٥١﴾", "w": [["الكتاب", "الخطّ والكتابة."], ["ورسولاً", "ويبعثه رسولاً."], ["آية", "علامة دالة على رسالته وصدق نبوته."], ["كهيئة الطير", "كصورة الطير."], ["الأكمه", "الذي وُلد أعمى."], ["الأبرص", "ذو البرص، وهو بياض يصيب الجلد، عجز عنه الطب القديم والحديث."], ["تدّخرون", "تحبسونه وتخفونه من الطعام وغيره."], ["لما بين يديّ", "لما كان قبلي."], ["إن الله ربي وربكم", "إلهي وإلهكم فاعبدوه."]], "m": "ما زال السياق في بيان حقيقة عيسى ﵇، وأنه عبد الله ورسوله، ليس ابن الله ولا إلهاً معه: أخبر أنه يخلقه بكلمة كن، ويعلّمه الكتاب والحكمة والتوراة والإنجيل وقد فعل، ويبعثه رسولاً إلى بني إسرائيل وقد فعل. فأخبرهم عيسى أنه جاءهم بآية من ربهم تدل على صدق رسالته: يصنع لهم من الطين كهيئة الطير وينفخ فيه فيكون طيراً بإذن الله، ويُبرئ الأكمه والأبرص ويحيي الموتى بإذن الله، وينبئهم بما يأكلون في بيوتهم وما يدّخرون فلا يخطئ. ثم قال: إن في ذلك لآية لكم إن كنتم مؤمنين، وقد جئتكم مصدّقاً لما قبلي من التوراة، ولأحلّ لكم بعض الذي حُرّم عليكم، فاتقوا الله وأطيعوني تنجوا وتسعدوا، إن الله ربي وربكم فاعبدوه، وعبادته وحده بما شرع هي الصراط المستقيم المفضي إلى الكمال والإسعاد في الدنيا والآخرة.", "h": ["شرف الكتابة وفضلها.", "فضل الحكمة، وهي الفقه في أسرار الشرع والإصابة في الأمور.", "الغيب لله، ويُعلم أنبياءه منه ما يشاء.", "ثبوت معجزات عيسى ﵇.", "لا إله إلا الله، ومحمد رسول الله، وعيسى كلمة الله وروح منه ورسول إلى بني إسرائيل.", "الأمر بالتقوى وطاعة الرسول؛ لتوقّف السعادة والكمال عليهما."], "k": "كل معجزات عيسى ﵇ كانت «بإذن الله»… فهل أنسب نجاحي لنفسي، أم أقول: بإذن الله؟"}, {"lbl": "الآيات ٥٢ – ٥٨", "q": "۞فَلَمَّآ أَحَسَّ عِيسَىٰ مِنۡهُمُ ٱلۡكُفۡرَ قَالَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشۡهَدۡ بِأَنَّا مُسۡلِمُونَ ﴿٥٢﴾ رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِينَ ﴿٥٣﴾ وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ ﴿٥٤﴾ إِذۡ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُواْ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۖ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ بَيۡنَكُمۡ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ ﴿٥٥﴾ فَأَمَّا ٱلَّذِينَ كَفَرُواْ فَأُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِينَ ﴿٥٦﴾ وَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّـٰلِمِينَ ﴿٥٧﴾ ذَٰلِكَ نَتۡلُوهُ عَلَيۡكَ مِنَ ٱلۡأٓيَٰتِ وَٱلذِّكۡرِ ٱلۡحَكِيمِ ﴿٥٨﴾", "w": [["أحسّ منهم الكفر", "علم منهم الكفر به وبما جاء به، وهمّهم بأذيّته."], ["الحواريون", "أصفياؤه وأصحابه."], ["مسلمون", "منقادون لأمر الله ورسوله مطيعون."], ["الشاهدين", "الذين يشهدون أن لا إله إلا الله ويعبدونه بما يجب أن يُعبد به."], ["مكروا", "دبّروا قتل المسيح ﵇."], ["ومكر الله", "دبّر لإنجائه وخيّبهم فيما عزموا عليه."], ["خير الماكرين", "أحسن المدبّرين لإنقاذ أوليائه وإهلاك أعدائه."], ["متوفّيك", "قابضك ومتمّم لك ما كتبت لك من البقاء مع قومك."], ["ورافعك إليّ", "إلى جواري في الملكوت الأعلى."], ["ومطهّرك", "منزّهك ومبعدك من رجسهم وكفرهم."], ["ذلك نتلوه عليك", "ذلك المذكور من أمر عيسى نقرؤه عليك من آيات القرآن الحكيم."]], "m": "ما زال السياق في الحِجاج مع وفد نجران: لما علم عيسى ﵇ من بني إسرائيل الكفر وهمّهم بأذيّته قال: من أنصاري إلى الله؟ فأجابه الحواريون، أصفياؤه: نحن أنصار الله، آمنا بالله واشهد بأنّا مسلمون، ربنا آمنا بما أنزلت واتبعنا الرسول فاكتبنا مع الشاهدين. ونفّذ اليهود مكرهم فحاصروا منزله ليأخذوه ويصلبوه، ومكر الله وهو خير الماكرين: قال لعبده عيسى: إني قابضك ورافعك إليّ، فرفعه إليه، وألقى شبهه على رئيس المهاجمين فظنّوه المسيح فقتلوه وصلبوه. ومطهّرك من تُهم اليهود الباطلة إذ قالوا: ساحر وابن زنى، ومبعدك عن مجتمعهم الذي فسد بكفرهم. ووعده أن يجعل الذين اتبعوه على الإيمان والإسلام فوق الذين كفروا إلى يوم القيامة، وقد أنجز وعده فأعزّ أهل الإسلام وأذلّ اليهود. ثم يرجع الجميع إليه يوم القيامة فيحكم بينهم: فأما الذين كفروا فيعذّبهم عذاباً شديداً في الدنيا بالقتل والذلة وفي الآخرة بالنار، وما لهم من ناصرين، وأما الذين آمنوا وعملوا الصالحات فيوفّيهم أجورهم نصراً وتمكيناً في الدنيا وجنات في الآخرة، والله لا يحب الظالمين، فكيف يظلم عباده؟ ذلك نتلوه عليك من الآيات والذكر الحكيم.", "h": ["قيام الحجة على نصارى نجران؛ إذ أخبرهم الرسول ﷺ بالوحي بأوصاف عيسى ﵇ وأحواله مع قومه، فتقرّر بطلان ألوهيته.", "الإسلام دين الأنبياء وسائر الأمم، ولا دين حق غيره.", "تقرير أن لكل نبي حواريين وأنصاراً.", "فضل أهل لا إله إلا الله؛ إذ هم الشاهدون بالحق والناطقون به.", "تقرير قبض الله لعيسى ﵇ ورفعه إليه حياً، ونزوله في آخر الدنيا ليحكم زمناً ثم يموت الموتة التي كتبها الله على كل إنسان؛ فلم يجمع الله له بين موتتين، وهذا دليل أنه رُفع حياً لا ميتاً.", "صدق وعد الله بعزّة أهل الإسلام."], "k": "«من أنصاري إلى الله؟»… لو سُئلتُ هذا السؤال اليوم، ما الذي أقدّمه نصرةً لدين الله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 48;
insert into public.tdb_cards(topic, i, body) select 48, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٥ – ٤٧", "q": "إِذۡ قَالَتِ ٱلۡمَلَـٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٖ مِّنۡهُ ٱسۡمُهُ ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ وَجِيهٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمِنَ ٱلۡمُقَرَّبِينَ ﴿٤٥﴾ وَيُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗا وَمِنَ ٱلصَّـٰلِحِينَ ﴿٤٦﴾ قَالَتۡ رَبِّ أَنَّىٰ يَكُونُ لِي وَلَدٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخۡلُقُ مَا يَشَآءُۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ ﴿٤٧﴾", "w": [["يبشّرك", "يخبرك بخبر سارّ مفرح."], ["بكلمة منه", "هو المسيح ﵇، وسُمّي كلمة لأنه كان بكلمة الله: كن."], ["المسيح", "لقب عيسى ﵇، ومن معانيه: الصدّيق."], ["وجيهاً", "ذا جاه وقدر وشرف بين الناس."], ["وكهلاً", "الكهولة: سنّ ما بين الشباب والشيخوخة."], ["ولم يمسسني بشر", "لم يقربني رجل."], ["قضى أمراً", "أراده وحكم بوجوده."]], "m": "ما زال السياق في حِجاج وفد نصارى نجران: واذكر لهم إذ قالت الملائكة يا مريم إن الله يبشّرك بكلمة منه، إذ أخبرها جبريل ﵇ بأن الله يبشّرها بولد يكون بكلمة الله، اسمه المسيح عيسى ابن مريم، ذو جاه وشرف في الدنيا والآخرة ومن المقربين، يكلّم الناس في مهده وقت رضاعه كما يكلمهم في كهولته، ومن الصالحين الذين يؤدّون حقوق الله وحقوق عباده. فقالت مريم: رب أنّى يكون لي ولد ولم يمسسني بشر، وسنّتك في خلق الولد الاتصال؟ فأجابها جبريل: الأمر كذلك، سيخلق الله منك ولداً من غير أب، وهو يخلق ما يشاء، إذا قضى أمراً فإنما يقول له كن فيكون.", "h": ["بيان شرف مريم وكرامتها على ربها، إذ كلّمها جبريل وبشّرها بعد أن تمثّل لها بشراً.", "بيان شرف عيسى ﵇ ووجاهته في الدنيا والآخرة، وأنه من المقربين والصالحين.", "تكلّم عيسى ﵇ في المهد آية من آيات الله؛ إذ لم تجرِ العادة أن يتكلم الرضيع في مهده.", "جواز طلب الاستفسار عما يكون مخالفاً للعادة لمعرفة سرّه أو علّته أو حكمته."], "k": "«إذا قضى أمراً فإنما يقول له كن فيكون»… ما الأمر الذي أظنه مستحيلاً وأحتاج أن أتذكّر معه هذه الآية؟"}, {"lbl": "الآيات ٤٨ – ٥١", "q": "وَيُعَلِّمُهُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ ﴿٤٨﴾ وَرَسُولًا إِلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ أَنِّي قَدۡ جِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ أَنِّيٓ أَخۡلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيۡرَۢا بِإِذۡنِ ٱللَّهِۖ وَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ وَأُحۡيِ ٱلۡمَوۡتَىٰ بِإِذۡنِ ٱللَّهِۖ وَأُنَبِّئُكُم بِمَا تَأۡكُلُونَ وَمَا تَدَّخِرُونَ فِي بُيُوتِكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ ﴿٤٩﴾ وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡۚ وَجِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ ﴿٥٠﴾ إِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ﴿٥١﴾", "w": [["الكتاب", "الخطّ والكتابة."], ["ورسولاً", "ويبعثه رسولاً."], ["آية", "علامة دالة على رسالته وصدق نبوته."], ["كهيئة الطير", "كصورة الطير."], ["الأكمه", "الذي وُلد أعمى."], ["الأبرص", "ذو البرص، وهو بياض يصيب الجلد، عجز عنه الطب القديم والحديث."], ["تدّخرون", "تحبسونه وتخفونه من الطعام وغيره."], ["لما بين يديّ", "لما كان قبلي."], ["إن الله ربي وربكم", "إلهي وإلهكم فاعبدوه."]], "m": "ما زال السياق في بيان حقيقة عيسى ﵇، وأنه عبد الله ورسوله، ليس ابن الله ولا إلهاً معه: أخبر أنه يخلقه بكلمة كن، ويعلّمه الكتاب والحكمة والتوراة والإنجيل وقد فعل، ويبعثه رسولاً إلى بني إسرائيل وقد فعل. فأخبرهم عيسى أنه جاءهم بآية من ربهم تدل على صدق رسالته: يصنع لهم من الطين كهيئة الطير وينفخ فيه فيكون طيراً بإذن الله، ويُبرئ الأكمه والأبرص ويحيي الموتى بإذن الله، وينبئهم بما يأكلون في بيوتهم وما يدّخرون فلا يخطئ. ثم قال: إن في ذلك لآية لكم إن كنتم مؤمنين، وقد جئتكم مصدّقاً لما قبلي من التوراة، ولأحلّ لكم بعض الذي حُرّم عليكم، فاتقوا الله وأطيعوني تنجوا وتسعدوا، إن الله ربي وربكم فاعبدوه، وعبادته وحده بما شرع هي الصراط المستقيم المفضي إلى الكمال والإسعاد في الدنيا والآخرة.", "h": ["شرف الكتابة وفضلها.", "فضل الحكمة، وهي الفقه في أسرار الشرع والإصابة في الأمور.", "الغيب لله، ويُعلم أنبياءه منه ما يشاء.", "ثبوت معجزات عيسى ﵇.", "لا إله إلا الله، ومحمد رسول الله، وعيسى كلمة الله وروح منه ورسول إلى بني إسرائيل.", "الأمر بالتقوى وطاعة الرسول؛ لتوقّف السعادة والكمال عليهما."], "k": "كل معجزات عيسى ﵇ كانت «بإذن الله»… فهل أنسب نجاحي لنفسي، أم أقول: بإذن الله؟"}, {"lbl": "الآيات ٥٢ – ٥٨", "q": "۞فَلَمَّآ أَحَسَّ عِيسَىٰ مِنۡهُمُ ٱلۡكُفۡرَ قَالَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشۡهَدۡ بِأَنَّا مُسۡلِمُونَ ﴿٥٢﴾ رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِينَ ﴿٥٣﴾ وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ ﴿٥٤﴾ إِذۡ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُواْ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۖ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ بَيۡنَكُمۡ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ ﴿٥٥﴾ فَأَمَّا ٱلَّذِينَ كَفَرُواْ فَأُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِينَ ﴿٥٦﴾ وَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّـٰلِمِينَ ﴿٥٧﴾ ذَٰلِكَ نَتۡلُوهُ عَلَيۡكَ مِنَ ٱلۡأٓيَٰتِ وَٱلذِّكۡرِ ٱلۡحَكِيمِ ﴿٥٨﴾", "w": [["أحسّ منهم الكفر", "علم منهم الكفر به وبما جاء به، وهمّهم بأذيّته."], ["الحواريون", "أصفياؤه وأصحابه."], ["مسلمون", "منقادون لأمر الله ورسوله مطيعون."], ["الشاهدين", "الذين يشهدون أن لا إله إلا الله ويعبدونه بما يجب أن يُعبد به."], ["مكروا", "دبّروا قتل المسيح ﵇."], ["ومكر الله", "دبّر لإنجائه وخيّبهم فيما عزموا عليه."], ["خير الماكرين", "أحسن المدبّرين لإنقاذ أوليائه وإهلاك أعدائه."], ["متوفّيك", "قابضك ومتمّم لك ما كتبت لك من البقاء مع قومك."], ["ورافعك إليّ", "إلى جواري في الملكوت الأعلى."], ["ومطهّرك", "منزّهك ومبعدك من رجسهم وكفرهم."], ["ذلك نتلوه عليك", "ذلك المذكور من أمر عيسى نقرؤه عليك من آيات القرآن الحكيم."]], "m": "ما زال السياق في الحِجاج مع وفد نجران: لما علم عيسى ﵇ من بني إسرائيل الكفر وهمّهم بأذيّته قال: من أنصاري إلى الله؟ فأجابه الحواريون، أصفياؤه: نحن أنصار الله، آمنا بالله واشهد بأنّا مسلمون، ربنا آمنا بما أنزلت واتبعنا الرسول فاكتبنا مع الشاهدين. ونفّذ اليهود مكرهم فحاصروا منزله ليأخذوه ويصلبوه، ومكر الله وهو خير الماكرين: قال لعبده عيسى: إني قابضك ورافعك إليّ، فرفعه إليه، وألقى شبهه على رئيس المهاجمين فظنّوه المسيح فقتلوه وصلبوه. ومطهّرك من تُهم اليهود الباطلة إذ قالوا: ساحر وابن زنى، ومبعدك عن مجتمعهم الذي فسد بكفرهم. ووعده أن يجعل الذين اتبعوه على الإيمان والإسلام فوق الذين كفروا إلى يوم القيامة، وقد أنجز وعده فأعزّ أهل الإسلام وأذلّ اليهود. ثم يرجع الجميع إليه يوم القيامة فيحكم بينهم: فأما الذين كفروا فيعذّبهم عذاباً شديداً في الدنيا بالقتل والذلة وفي الآخرة بالنار، وما لهم من ناصرين، وأما الذين آمنوا وعملوا الصالحات فيوفّيهم أجورهم نصراً وتمكيناً في الدنيا وجنات في الآخرة، والله لا يحب الظالمين، فكيف يظلم عباده؟ ذلك نتلوه عليك من الآيات والذكر الحكيم.", "h": ["قيام الحجة على نصارى نجران؛ إذ أخبرهم الرسول ﷺ بالوحي بأوصاف عيسى ﵇ وأحواله مع قومه، فتقرّر بطلان ألوهيته.", "الإسلام دين الأنبياء وسائر الأمم، ولا دين حق غيره.", "تقرير أن لكل نبي حواريين وأنصاراً.", "فضل أهل لا إله إلا الله؛ إذ هم الشاهدون بالحق والناطقون به.", "تقرير قبض الله لعيسى ﵇ ورفعه إليه حياً، ونزوله في آخر الدنيا ليحكم زمناً ثم يموت الموتة التي كتبها الله على كل إنسان؛ فلم يجمع الله له بين موتتين، وهذا دليل أنه رُفع حياً لا ميتاً.", "صدق وعد الله بعزّة أهل الإسلام."], "k": "«من أنصاري إلى الله؟»… لو سُئلتُ هذا السؤال اليوم، ما الذي أقدّمه نصرةً لدين الله؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (49, 3, 59, 68, 'سورة آل عمران ٥٩ – ٦٨', 'مثل عيسى كمثل آدم، والكلمة السواء، وملة إبراهيم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 49) = $j$[{"lbl": "الآيات ٥٩ – ٦٣", "q": "إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابٖ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ ﴿٥٩﴾ ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ ﴿٦٠﴾ فَمَنۡ حَآجَّكَ فِيهِ مِنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ فَقُلۡ تَعَالَوۡاْ نَدۡعُ أَبۡنَآءَنَا وَأَبۡنَآءَكُمۡ وَنِسَآءَنَا وَنِسَآءَكُمۡ وَأَنفُسَنَا وَأَنفُسَكُمۡ ثُمَّ نَبۡتَهِلۡ فَنَجۡعَل لَّعۡنَتَ ٱللَّهِ عَلَى ٱلۡكَٰذِبِينَ ﴿٦١﴾ إِنَّ هَٰذَا لَهُوَ ٱلۡقَصَصُ ٱلۡحَقُّۚ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٦٢﴾ فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ عَلِيمُۢ بِٱلۡمُفۡسِدِينَ ﴿٦٣﴾", "w": [["المثل", "الصفة المستغربة البديعة."], ["الحق من ربك", "ما قصصناه عليك في شأن عيسى ﵇ هو الحق الثابت من ربك."], ["الممترين", "الشاكّين؛ إذ الامتراء: الشك."], ["حاجّك", "جادلك بالحجج."], ["نبتهل", "نلتعن، أي نلعن الكاذب منا."], ["القصص الحق", "ما قصّه الله هو القصص الحق الثابت الذي لا شك فيه."], ["المفسدين", "الذين يعملون بمعاصي الله في الأرض من الشرك وكبائر الذنوب."]], "m": "ما زال السياق في تقرير عبودية عيسى ﵇ ورسالته دون ربوبيته وألوهيته؛ فقد رُوي أن وفد نجران قالوا للرسول ﷺ: كل آدمي له أب، فما شأن عيسى لا أب له؟ فأنزل الله: «إن مثل عيسى عند الله كمثل آدم خلقه من تراب ثم قال له كن فيكون»؛ فأيّ داعٍ لاتخاذ عيسى إلهاً لكونه خُلق من غير أب، وآدم خُلق بلا أب ولا أم بكلمة الله؟ هذا هو الحق من ربك فلا تكن من الشاكّين. ولما أكثروا على الرسول ﷺ من الجدال أرشده ربه إلى طريق التخلص منهم وهو المباهلة: أن يجتمعوا هم وأبناؤهم ونساؤهم وأنفسهم، ثم يقول كل فريق: اللهم العن الكاذب منا. وخرج الرسول ﷺ ومعه الحسن والحسين وفاطمة رضي الله عنهم، إلا أن النصارى عرفوا الحق وخافوا إن لاعنوا أن يهلكوا، فأبوا الملاعنة، ودعاهم إلى الإسلام فأبوا حفاظاً على زعامتهم ودنياهم، ورضوا بالمصالحة. ثم قرّر أن هذا القصص الحق في شأن عيسى، وأنه لا إله إلا الله، وأنه العزيز الحكيم، وتوعّد أهل الفساد في الأرض بأنه عليم بهم.", "h": ["ولاية الله لرسوله ﷺ بإرشاده إلى الطريقة التي أنهى بها جدال النصارى الذي أتعبه.", "مشروعية المباهلة، غير أنها تكون من الصالحين الذين يُستجاب لهم.", "تقرير ألوهية الله دون سواه، وبطلان دعوى النصارى في تأليه عيسى ﵇.", "تهديد الله لأهل الفساد في الأرض، وهم الذين يعملون بالشرك والمعاصي."], "k": "عرفوا الحق ثم رفضوه حفاظاً على مكانتهم… هل تمنعني مكانتي يوماً من الاعتراف بخطأ؟"}, {"lbl": "الآيات ٦٤ – ٦٨", "q": "قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـٔٗا وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ بِأَنَّا مُسۡلِمُونَ ﴿٦٤﴾ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تُحَآجُّونَ فِيٓ إِبۡرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوۡرَىٰةُ وَٱلۡإِنجِيلُ إِلَّا مِنۢ بَعۡدِهِۦٓۚ أَفَلَا تَعۡقِلُونَ ﴿٦٥﴾ هَـٰٓأَنتُمۡ هَـٰٓؤُلَآءِ حَٰجَجۡتُمۡ فِيمَا لَكُم بِهِۦ عِلۡمٞ فَلِمَ تُحَآجُّونَ فِيمَا لَيۡسَ لَكُم بِهِۦ عِلۡمٞۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ﴿٦٦﴾ مَا كَانَ إِبۡرَٰهِيمُ يَهُودِيّٗا وَلَا نَصۡرَانِيّٗا وَلَٰكِن كَانَ حَنِيفٗا مُّسۡلِمٗا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ ﴿٦٧﴾ إِنَّ أَوۡلَى ٱلنَّاسِ بِإِبۡرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِيُّ وَٱلَّذِينَ ءَامَنُواْۗ وَٱللَّهُ وَلِيُّ ٱلۡمُؤۡمِنِينَ ﴿٦٨﴾", "w": [["أهل الكتاب", "اليهود أهل التوراة، والنصارى أهل الإنجيل."], ["إلى كلمة سواء", "الكلمة العادلة: أن نعبد الله وحده لا شريك له، ولا يتخذ بعضنا بعضاً أرباباً من دون الله."], ["أرباباً", "جمع ربّ، وهو المطاع بغير طاعة الله."], ["فإن تولّوا", "أعرضوا عن التوحيد."], ["اشهدوا", "اعلموا علم رؤية ومشاهدة بأنّا مسلمون."], ["تحاجّون", "تجادلون بحجج باطلة."], ["حنيفاً مسلماً", "مائلاً عن الملل الباطلة إلى ملة الحق وهي الإسلام."], ["أولى الناس بإبراهيم", "أحقهم بالنسبة إليه وموالاته: الذين اتبعوه على التوحيد."], ["والله وليّ المؤمنين", "متولّي أمرهم وناصرهم."]], "m": "ما زال السياق في إبطال باطل أهل الكتابين: قل لهم يا رسولنا: تعالوا، ارتفعوا من وهدة الباطل إلى كلمة عدل بيننا: أن نعبد الله وحده لا نشرك به شيئاً، ولا يتخذ بعضنا بعضاً أرباباً فيفرض طاعته على غيره، فإن تولّوا فقولوا: اشهدوا بأنّا مسلمون. ثم قال: يا أهل الكتاب لمَ تحاجّون في إبراهيم، فتدّعي كل طائفة أنه كان على دينها، واليهودية ما كانت إلا بعد نزول التوراة، والنصرانية بعد نزول الإنجيل، وإبراهيم قبلهما بمئات السنين؟ أفلا تعقلون؟ ها أنتم جادلتم فيما لكم به علم من شأن دينكم، فلمَ تجادلون فيما ليس لكم به علم من شأن إبراهيم وملته؟ والله يعلم وأنتم لا تعلمون. ثم كذّبهم: ما كان إبراهيم يهودياً ولا نصرانياً، ولكن كان حنيفاً مسلماً وما كان من المشركين. وقرّر أن أحق الناس بالانتماء إلى إبراهيم الذين اتبعوه على التوحيد، وهذا النبي محمد ﷺ والذين آمنوا معه، والله وليّ المؤمنين.", "h": ["لا يصلح حال البشرية ولا يستقيم أمرها إلا بالكلمة السواء: أن تعبد ربها وحده لا تشرك به، وألا يعلو بعضها على بعض تحت أي قانون أو شعار.", "حجّية التاريخ والحاجة إليه؛ إذ ردّ الله على أهل الكتاب بأن التوراة والإنجيل لم ينزلا إلا بعد إبراهيم، فكيف يكون يهودياً أو نصرانياً؟", "ذم من يجادل فيما لا علم له به ولا شأن له فيه.", "اليهودية كالنصرانية لم تكن دين الله، وإنما هما بدعتان لا غير.", "المؤمنون بعضهم أولياء بعض وإن تباعدت ديارهم، والله وليّ المؤمنين."], "k": "هل جادلتُ يوماً فيما ليس لي به علم؟ ماذا لو قلت ببساطة: لا أعلم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 49;
insert into public.tdb_cards(topic, i, body) select 49, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٩ – ٦٣", "q": "إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابٖ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ ﴿٥٩﴾ ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ ﴿٦٠﴾ فَمَنۡ حَآجَّكَ فِيهِ مِنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ فَقُلۡ تَعَالَوۡاْ نَدۡعُ أَبۡنَآءَنَا وَأَبۡنَآءَكُمۡ وَنِسَآءَنَا وَنِسَآءَكُمۡ وَأَنفُسَنَا وَأَنفُسَكُمۡ ثُمَّ نَبۡتَهِلۡ فَنَجۡعَل لَّعۡنَتَ ٱللَّهِ عَلَى ٱلۡكَٰذِبِينَ ﴿٦١﴾ إِنَّ هَٰذَا لَهُوَ ٱلۡقَصَصُ ٱلۡحَقُّۚ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٦٢﴾ فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ عَلِيمُۢ بِٱلۡمُفۡسِدِينَ ﴿٦٣﴾", "w": [["المثل", "الصفة المستغربة البديعة."], ["الحق من ربك", "ما قصصناه عليك في شأن عيسى ﵇ هو الحق الثابت من ربك."], ["الممترين", "الشاكّين؛ إذ الامتراء: الشك."], ["حاجّك", "جادلك بالحجج."], ["نبتهل", "نلتعن، أي نلعن الكاذب منا."], ["القصص الحق", "ما قصّه الله هو القصص الحق الثابت الذي لا شك فيه."], ["المفسدين", "الذين يعملون بمعاصي الله في الأرض من الشرك وكبائر الذنوب."]], "m": "ما زال السياق في تقرير عبودية عيسى ﵇ ورسالته دون ربوبيته وألوهيته؛ فقد رُوي أن وفد نجران قالوا للرسول ﷺ: كل آدمي له أب، فما شأن عيسى لا أب له؟ فأنزل الله: «إن مثل عيسى عند الله كمثل آدم خلقه من تراب ثم قال له كن فيكون»؛ فأيّ داعٍ لاتخاذ عيسى إلهاً لكونه خُلق من غير أب، وآدم خُلق بلا أب ولا أم بكلمة الله؟ هذا هو الحق من ربك فلا تكن من الشاكّين. ولما أكثروا على الرسول ﷺ من الجدال أرشده ربه إلى طريق التخلص منهم وهو المباهلة: أن يجتمعوا هم وأبناؤهم ونساؤهم وأنفسهم، ثم يقول كل فريق: اللهم العن الكاذب منا. وخرج الرسول ﷺ ومعه الحسن والحسين وفاطمة رضي الله عنهم، إلا أن النصارى عرفوا الحق وخافوا إن لاعنوا أن يهلكوا، فأبوا الملاعنة، ودعاهم إلى الإسلام فأبوا حفاظاً على زعامتهم ودنياهم، ورضوا بالمصالحة. ثم قرّر أن هذا القصص الحق في شأن عيسى، وأنه لا إله إلا الله، وأنه العزيز الحكيم، وتوعّد أهل الفساد في الأرض بأنه عليم بهم.", "h": ["ولاية الله لرسوله ﷺ بإرشاده إلى الطريقة التي أنهى بها جدال النصارى الذي أتعبه.", "مشروعية المباهلة، غير أنها تكون من الصالحين الذين يُستجاب لهم.", "تقرير ألوهية الله دون سواه، وبطلان دعوى النصارى في تأليه عيسى ﵇.", "تهديد الله لأهل الفساد في الأرض، وهم الذين يعملون بالشرك والمعاصي."], "k": "عرفوا الحق ثم رفضوه حفاظاً على مكانتهم… هل تمنعني مكانتي يوماً من الاعتراف بخطأ؟"}, {"lbl": "الآيات ٦٤ – ٦٨", "q": "قُلۡ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـٔٗا وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ بِأَنَّا مُسۡلِمُونَ ﴿٦٤﴾ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تُحَآجُّونَ فِيٓ إِبۡرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوۡرَىٰةُ وَٱلۡإِنجِيلُ إِلَّا مِنۢ بَعۡدِهِۦٓۚ أَفَلَا تَعۡقِلُونَ ﴿٦٥﴾ هَـٰٓأَنتُمۡ هَـٰٓؤُلَآءِ حَٰجَجۡتُمۡ فِيمَا لَكُم بِهِۦ عِلۡمٞ فَلِمَ تُحَآجُّونَ فِيمَا لَيۡسَ لَكُم بِهِۦ عِلۡمٞۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ﴿٦٦﴾ مَا كَانَ إِبۡرَٰهِيمُ يَهُودِيّٗا وَلَا نَصۡرَانِيّٗا وَلَٰكِن كَانَ حَنِيفٗا مُّسۡلِمٗا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ ﴿٦٧﴾ إِنَّ أَوۡلَى ٱلنَّاسِ بِإِبۡرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِيُّ وَٱلَّذِينَ ءَامَنُواْۗ وَٱللَّهُ وَلِيُّ ٱلۡمُؤۡمِنِينَ ﴿٦٨﴾", "w": [["أهل الكتاب", "اليهود أهل التوراة، والنصارى أهل الإنجيل."], ["إلى كلمة سواء", "الكلمة العادلة: أن نعبد الله وحده لا شريك له، ولا يتخذ بعضنا بعضاً أرباباً من دون الله."], ["أرباباً", "جمع ربّ، وهو المطاع بغير طاعة الله."], ["فإن تولّوا", "أعرضوا عن التوحيد."], ["اشهدوا", "اعلموا علم رؤية ومشاهدة بأنّا مسلمون."], ["تحاجّون", "تجادلون بحجج باطلة."], ["حنيفاً مسلماً", "مائلاً عن الملل الباطلة إلى ملة الحق وهي الإسلام."], ["أولى الناس بإبراهيم", "أحقهم بالنسبة إليه وموالاته: الذين اتبعوه على التوحيد."], ["والله وليّ المؤمنين", "متولّي أمرهم وناصرهم."]], "m": "ما زال السياق في إبطال باطل أهل الكتابين: قل لهم يا رسولنا: تعالوا، ارتفعوا من وهدة الباطل إلى كلمة عدل بيننا: أن نعبد الله وحده لا نشرك به شيئاً، ولا يتخذ بعضنا بعضاً أرباباً فيفرض طاعته على غيره، فإن تولّوا فقولوا: اشهدوا بأنّا مسلمون. ثم قال: يا أهل الكتاب لمَ تحاجّون في إبراهيم، فتدّعي كل طائفة أنه كان على دينها، واليهودية ما كانت إلا بعد نزول التوراة، والنصرانية بعد نزول الإنجيل، وإبراهيم قبلهما بمئات السنين؟ أفلا تعقلون؟ ها أنتم جادلتم فيما لكم به علم من شأن دينكم، فلمَ تجادلون فيما ليس لكم به علم من شأن إبراهيم وملته؟ والله يعلم وأنتم لا تعلمون. ثم كذّبهم: ما كان إبراهيم يهودياً ولا نصرانياً، ولكن كان حنيفاً مسلماً وما كان من المشركين. وقرّر أن أحق الناس بالانتماء إلى إبراهيم الذين اتبعوه على التوحيد، وهذا النبي محمد ﷺ والذين آمنوا معه، والله وليّ المؤمنين.", "h": ["لا يصلح حال البشرية ولا يستقيم أمرها إلا بالكلمة السواء: أن تعبد ربها وحده لا تشرك به، وألا يعلو بعضها على بعض تحت أي قانون أو شعار.", "حجّية التاريخ والحاجة إليه؛ إذ ردّ الله على أهل الكتاب بأن التوراة والإنجيل لم ينزلا إلا بعد إبراهيم، فكيف يكون يهودياً أو نصرانياً؟", "ذم من يجادل فيما لا علم له به ولا شأن له فيه.", "اليهودية كالنصرانية لم تكن دين الله، وإنما هما بدعتان لا غير.", "المؤمنون بعضهم أولياء بعض وإن تباعدت ديارهم، والله وليّ المؤمنين."], "k": "هل جادلتُ يوماً فيما ليس لي به علم؟ ماذا لو قلت ببساطة: لا أعلم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (50, 3, 69, 74, 'سورة آل عمران ٦٩ – ٧٤', 'كيد أهل الكتاب للمؤمنين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 50) = $j$[{"lbl": "الآيات ٦٩ – ٧١", "q": "وَدَّت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يُضِلُّونَكُمۡ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ ﴿٦٩﴾ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمۡ تَشۡهَدُونَ ﴿٧٠﴾ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَلۡبِسُونَ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُونَ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ ﴿٧١﴾", "w": [["ودّت طائفة", "أحبّت فرقة، وهم الأحبار والرؤساء فيهم."], ["لو يضلّونكم", "تمنّوا إيقاعكم في الضلال لتشقوا وتهلكوا مثلهم."], ["وما يشعرون", "وما يدرون أنهم بمحاولة إضلال المؤمنين إنما يضلّون أنفسهم، فيضاعَف لهم العذاب."], ["تلبسون الحق بالباطل", "تخلطونه به، كأنما كسوتم الباطل ثوب الحق والحق ثوب الباطل، حتى لا يُعرف."]], "m": "يخبر الله عباده المؤمنين أن فرقة من أهل الكتاب، وغالبها في رؤسائهم من الأحبار والقسس، تمنّت لو أوقعتكم في الضلال لتهلكوا، حسداً لكم على الحق الذي أنتم عليه، وأخبر أنهم بتمنّيهم هلاك المسلمين إنما يُهلكون أنفسهم وما يشعرون. ثم نادى أهل الكتاب موبّخاً: لمَ تكفرون بآيات الله، أي تجحدون الآيات التي فيها نعت الرسول ﷺ في التوراة والإنجيل، وأنتم تشهدون أنها منطبقة عليه؟ ووبّخهم على خلط الحق بالباطل حتى لا يُعرف فيُهتدى به، وعلى كتمانهم الحق، وهو نبوة محمد ﷺ المبيّنة في كتبهم، وهم يعلمون أنه الحق.", "h": ["بيان رغبة كثير من اليهود والنصارى في إضلال المسلمين وإهلاكهم.", "عاقبة الشر والفساد تعود على صاحبها في نهاية الأمر.", "قبح من يكتم الحق وهو يعرفه.", "حرمة التدليس والتلبيس في كل شيء، لا سيما في دين الله لإبعاد الناس عنه.", "حرمة كتمان الحق في الشهادة وغيرها."], "k": "هل خلطتُ يوماً حقاً بباطل لأكسب جدالاً أو أدافع عن نفسي؟"}, {"lbl": "الآيات ٧٢ – ٧٤", "q": "وَقَالَت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ ءَامِنُواْ بِٱلَّذِيٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَجۡهَ ٱلنَّهَارِ وَٱكۡفُرُوٓاْ ءَاخِرَهُۥ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٧٢﴾ وَلَا تُؤۡمِنُوٓاْ إِلَّا لِمَن تَبِعَ دِينَكُمۡ قُلۡ إِنَّ ٱلۡهُدَىٰ هُدَى ٱللَّهِ أَن يُؤۡتَىٰٓ أَحَدٞ مِّثۡلَ مَآ أُوتِيتُمۡ أَوۡ يُحَآجُّوكُمۡ عِندَ رَبِّكُمۡۗ قُلۡ إِنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ﴿٧٣﴾ يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ ﴿٧٤﴾", "w": [["وجه النهار وآخره", "أوله وهو الصباح، وآخره وهو المساء."], ["ولا تؤمنوا إلا لمن تبع دينكم", "لا تصدّقوا إلا من كان على ملتكم."], ["إن الهدى هدى الله", "البيان الحق والتوفيق الكامل بيان الله وهداه، لا ما يخلطه اليهود تضليلاً للناس."], ["أن يُؤتى أحد مثل ما أوتيتم", "أن يُعطى أحد نبوة وديناً وفضلاً."], ["أو يحاجّوكم عند ربكم", "يخاصموكم يوم القيامة عند ربكم."], ["إن الفضل بيد الله", "التوفيق للإيمان والهداية بيد الله لا بيد غيره."], ["واسع عليم", "ذو سعة في فضله، عليم بمن يستحقه."]], "m": "يخبر الله عن كيد اليهود ومكرهم بالمسلمين: قالت طائفة منهم: آمنوا بالذي أُنزل على المؤمنين أول النهار واكفروا آخره لعلهم يرجعون؛ وذلك أن بعض رؤسائهم قالوا لإخوانهم: صلّوا مع المسلمين الصبح إلى الكعبة، وصلّوا العصر إلى بيت المقدس، فإن سُئلتم قولوا: تبيّن لنا أن الحق استقبال بيت المقدس؛ والغرض بلبلة أفكار المسلمين وإدخال الشك عليهم. وقال رؤساؤهم لأتباعهم: لا تصدّقوا إلا من تبع دينكم، ولا تعترفوا بأن أحداً أوتي مثل ما أوتيتم من النبوة والدين، كراهة أن يثبت المسلمون على دينهم، ولئلا يحتجّوا عليكم يوم القيامة باعترافكم. فردّ الله عليهم: قل إن الهدى هدى الله، وقل إن الفضل بيد الله يؤتيه من يشاء من عباده، لا بيد اليهود، والله واسع عليم، يختص برحمته من يشاء، والله ذو الفضل العظيم.", "h": ["تسجيل المكر والخداع على اليهود، وأنه من صفاتهم اللازمة لهم.", "الكشف عن التعصب اليهودي وأساليب التمويه والتضليل.", "سذاجة اليهود في فهم مسائل الاعتقاد؛ وإلا فأيّ مؤمن بالله واليوم الآخر يقول: لا تعترفوا للمسلمين بأنهم على حق حتى لا يحتجّوا عليكم باعترافكم يوم القيامة؟", "الله يعلم أنهم يجحدون الإسلام وهو الحق، وكتمانهم ذلك لا ينجيهم من عذابه."], "k": "«قل إن الفضل بيد الله»… هل أنزعج حين يُعطى غيري خيراً، أم أسأل الله من فضله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 50;
insert into public.tdb_cards(topic, i, body) select 50, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٩ – ٧١", "q": "وَدَّت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يُضِلُّونَكُمۡ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ ﴿٦٩﴾ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمۡ تَشۡهَدُونَ ﴿٧٠﴾ يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَلۡبِسُونَ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُونَ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ ﴿٧١﴾", "w": [["ودّت طائفة", "أحبّت فرقة، وهم الأحبار والرؤساء فيهم."], ["لو يضلّونكم", "تمنّوا إيقاعكم في الضلال لتشقوا وتهلكوا مثلهم."], ["وما يشعرون", "وما يدرون أنهم بمحاولة إضلال المؤمنين إنما يضلّون أنفسهم، فيضاعَف لهم العذاب."], ["تلبسون الحق بالباطل", "تخلطونه به، كأنما كسوتم الباطل ثوب الحق والحق ثوب الباطل، حتى لا يُعرف."]], "m": "يخبر الله عباده المؤمنين أن فرقة من أهل الكتاب، وغالبها في رؤسائهم من الأحبار والقسس، تمنّت لو أوقعتكم في الضلال لتهلكوا، حسداً لكم على الحق الذي أنتم عليه، وأخبر أنهم بتمنّيهم هلاك المسلمين إنما يُهلكون أنفسهم وما يشعرون. ثم نادى أهل الكتاب موبّخاً: لمَ تكفرون بآيات الله، أي تجحدون الآيات التي فيها نعت الرسول ﷺ في التوراة والإنجيل، وأنتم تشهدون أنها منطبقة عليه؟ ووبّخهم على خلط الحق بالباطل حتى لا يُعرف فيُهتدى به، وعلى كتمانهم الحق، وهو نبوة محمد ﷺ المبيّنة في كتبهم، وهم يعلمون أنه الحق.", "h": ["بيان رغبة كثير من اليهود والنصارى في إضلال المسلمين وإهلاكهم.", "عاقبة الشر والفساد تعود على صاحبها في نهاية الأمر.", "قبح من يكتم الحق وهو يعرفه.", "حرمة التدليس والتلبيس في كل شيء، لا سيما في دين الله لإبعاد الناس عنه.", "حرمة كتمان الحق في الشهادة وغيرها."], "k": "هل خلطتُ يوماً حقاً بباطل لأكسب جدالاً أو أدافع عن نفسي؟"}, {"lbl": "الآيات ٧٢ – ٧٤", "q": "وَقَالَت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ ءَامِنُواْ بِٱلَّذِيٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَجۡهَ ٱلنَّهَارِ وَٱكۡفُرُوٓاْ ءَاخِرَهُۥ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٧٢﴾ وَلَا تُؤۡمِنُوٓاْ إِلَّا لِمَن تَبِعَ دِينَكُمۡ قُلۡ إِنَّ ٱلۡهُدَىٰ هُدَى ٱللَّهِ أَن يُؤۡتَىٰٓ أَحَدٞ مِّثۡلَ مَآ أُوتِيتُمۡ أَوۡ يُحَآجُّوكُمۡ عِندَ رَبِّكُمۡۗ قُلۡ إِنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ﴿٧٣﴾ يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ ﴿٧٤﴾", "w": [["وجه النهار وآخره", "أوله وهو الصباح، وآخره وهو المساء."], ["ولا تؤمنوا إلا لمن تبع دينكم", "لا تصدّقوا إلا من كان على ملتكم."], ["إن الهدى هدى الله", "البيان الحق والتوفيق الكامل بيان الله وهداه، لا ما يخلطه اليهود تضليلاً للناس."], ["أن يُؤتى أحد مثل ما أوتيتم", "أن يُعطى أحد نبوة وديناً وفضلاً."], ["أو يحاجّوكم عند ربكم", "يخاصموكم يوم القيامة عند ربكم."], ["إن الفضل بيد الله", "التوفيق للإيمان والهداية بيد الله لا بيد غيره."], ["واسع عليم", "ذو سعة في فضله، عليم بمن يستحقه."]], "m": "يخبر الله عن كيد اليهود ومكرهم بالمسلمين: قالت طائفة منهم: آمنوا بالذي أُنزل على المؤمنين أول النهار واكفروا آخره لعلهم يرجعون؛ وذلك أن بعض رؤسائهم قالوا لإخوانهم: صلّوا مع المسلمين الصبح إلى الكعبة، وصلّوا العصر إلى بيت المقدس، فإن سُئلتم قولوا: تبيّن لنا أن الحق استقبال بيت المقدس؛ والغرض بلبلة أفكار المسلمين وإدخال الشك عليهم. وقال رؤساؤهم لأتباعهم: لا تصدّقوا إلا من تبع دينكم، ولا تعترفوا بأن أحداً أوتي مثل ما أوتيتم من النبوة والدين، كراهة أن يثبت المسلمون على دينهم، ولئلا يحتجّوا عليكم يوم القيامة باعترافكم. فردّ الله عليهم: قل إن الهدى هدى الله، وقل إن الفضل بيد الله يؤتيه من يشاء من عباده، لا بيد اليهود، والله واسع عليم، يختص برحمته من يشاء، والله ذو الفضل العظيم.", "h": ["تسجيل المكر والخداع على اليهود، وأنه من صفاتهم اللازمة لهم.", "الكشف عن التعصب اليهودي وأساليب التمويه والتضليل.", "سذاجة اليهود في فهم مسائل الاعتقاد؛ وإلا فأيّ مؤمن بالله واليوم الآخر يقول: لا تعترفوا للمسلمين بأنهم على حق حتى لا يحتجّوا عليكم باعترافكم يوم القيامة؟", "الله يعلم أنهم يجحدون الإسلام وهو الحق، وكتمانهم ذلك لا ينجيهم من عذابه."], "k": "«قل إن الفضل بيد الله»… هل أنزعج حين يُعطى غيري خيراً، أم أسأل الله من فضله؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (51, 3, 75, 83, 'سورة آل عمران ٧٥ – ٨٣', 'الأمانة، وتحريف الكلام، وميثاق النبيين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 51) = $j$[{"lbl": "الآيات ٧٥ – ٧٧", "q": "۞وَمِنۡ أَهۡلِ ٱلۡكِتَٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارٖ يُؤَدِّهِۦٓ إِلَيۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِينَارٖ لَّا يُؤَدِّهِۦٓ إِلَيۡكَ إِلَّا مَا دُمۡتَ عَلَيۡهِ قَآئِمٗاۗ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَيۡسَ عَلَيۡنَا فِي ٱلۡأُمِّيِّـۧنَ سَبِيلٞ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ ﴿٧٥﴾ بَلَىٰۚ مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ ﴿٧٦﴾ إِنَّ ٱلَّذِينَ يَشۡتَرُونَ بِعَهۡدِ ٱللَّهِ وَأَيۡمَٰنِهِمۡ ثَمَنٗا قَلِيلًا أُوْلَـٰٓئِكَ لَا خَلَٰقَ لَهُمۡ فِي ٱلۡأٓخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيۡهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿٧٧﴾", "w": [["إن تأمنه", "إن تجعله أميناً على شيء تضعه عنده."], ["بقنطار", "وزن معروف، والمراد هنا من الذهب."], ["إلا ما دمت عليه قائماً", "إلا إن لازمته تطالبه به ليل نهار."], ["الأميّين", "العرب المشركين."], ["ليس علينا في الأميين سبيل", "لا يؤاخذنا الله إن أكلنا أموالهم لأنهم مشركون."], ["بلى", "ليس الأمر كما يقولون، بل عليهم الإثم والمؤاخذة."], ["لا خلاق لهم", "لا حظّ ولا نصيب لهم في خيرات الآخرة ونعيم الجنان."], ["ولا يزكّيهم", "لا يطهّرهم من ذنوبهم ولا يكفّرها عنهم."]], "m": "ما زال السياق في هتك أستار أهل الكتاب وبيان صفاتهم الذميمة: فمنهم من إن ائتمنته على مال كثير أدّاه إليك كاملاً، ومنهم من إن ائتمنته على دينار خانك فيه وأنكره، فلا يؤدّيه إلا بملازمتك له ومطالبتك. وعلّة ذلك قولهم: لا حرج علينا في أكل أموال العرب لأنهم مشركون، فكذّبهم الله: «ويقولون على الله الكذب وهم يعلمون»، يكذبون ليسوّغوا خيانتهم. ثم قال: «بلى»، ليس الأمر كما يدّعون بل عليهم الإثم والمؤاخذة، وإنما لا إثم على من أوفى بعهد الله فآمن برسوله واتقى الشرك والمعاصي، فإن الله يحب المتقين. ثم توعّد بأشد العقوبات الذين يعاهدون ويخونون ويحلفون كاذبين من أجل حطام الدنيا: أولئك لا نصيب لهم في الآخرة، ولا يكلّمهم الله تشريفاً لهم، ولا ينظر إليهم يوم القيامة، ولا يزكّيهم، ولهم عذاب أليم.", "h": ["لا يُؤتمن اليهود ولا يُوثق بهم لما عُرفوا به من الخيانة.", "من كذب على الله أحرى به أن يكذب على الناس.", "بيان اعتقاد اليهود أن أموال غيرهم وأعراضهم مباحة لهم، لأنهم المؤمنون في نظرهم وغيرهم الكفار.", "عظم ذنب من يخون عهده من أجل المال، وكذا من يحلف كاذباً لأجل المال."], "k": "هل أنا أمين في القليل كما في الكثير، حتى في دينار لا يراه أحد؟"}, {"lbl": "الآية ٧٨", "q": "وَإِنَّ مِنۡهُمۡ لَفَرِيقٗا يَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَٰبِ لِتَحۡسَبُوهُ مِنَ ٱلۡكِتَٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَٰبِ وَيَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِۖ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ ﴿٧٨﴾", "w": [["وإن منهم لفريقاً", "طائفة من اليهود المعاصرين للنبي ﷺ بالمدينة."], ["يلوون ألسنتهم", "يحرّفون ألسنتهم بالكلام كأنهم يقرؤون الكتاب."], ["وما هو من الكتاب", "وليس هو من الكتاب."], ["ويقولون على الله الكذب", "يكذبون على الله لأغراض مادية."]], "m": "ما زال السياق في اليهود وبيان فضائحهم: أخبر تعالى أن طائفة منهم يحرّفون نطقهم بالكلام تمويهاً على السامعين، كأنهم يقرؤون ما أنزل الله في التوراة، وليس هو من الكتاب في شيء، بل هو الكذب البحت، ويقولون: هو من عند الله، وما هو من عند الله، ويقولون على الله الكذب وهم يعلمون، للحفاظ على الحطام الخسيس والرئاسة الكاذبة.", "h": ["بيان مكر اليهود وتضليلهم للناس وخداعهم باسم الدين والعلم.", "جرأة اليهود على الكذب على الناس وعلى الله مع علمهم بأنهم يكذبون، وهو أشدّ قبحاً وأعظم ظلماً.", "تحذير المسلم من سلوك اليهود في التضليل والقول على الله والرسول لأجل الأغراض الدنيوية الفاسدة."], "k": "قبل أن أنسب كلاماً لله أو لرسوله ﷺ… هل أتثبّت من صحته؟"}, {"lbl": "الآيتان ٧٩ – ٨٠", "q": "مَا كَانَ لِبَشَرٍ أَن يُؤۡتِيَهُ ٱللَّهُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُواْ عِبَادٗا لِّي مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُواْ رَبَّـٰنِيِّـۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ ٱلۡكِتَٰبَ وَبِمَا كُنتُمۡ تَدۡرُسُونَ ﴿٧٩﴾ وَلَا يَأۡمُرَكُمۡ أَن تَتَّخِذُواْ ٱلۡمَلَـٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرۡبَابًاۚ أَيَأۡمُرُكُم بِٱلۡكُفۡرِ بَعۡدَ إِذۡ أَنتُم مُّسۡلِمُونَ ﴿٨٠﴾", "w": [["ما كان لبشر", "لم يكن من شأن الإنسان الذي يؤتيه الله الكتاب والحكم والنبوة."], ["الكتاب والحكم والنبوة", "الكتاب: وحي الله المكتوب، والحكم: الحكمة وهي الفقه في أسرار الشرع، والنبوة: تشريف الله عبده بإنبائه بالغيب وتكليمه بالوحي."], ["ربّانيين", "جمع ربّاني: من يُنسب إلى الرب لكثرة عبادته وغزارة علمه، أو الذي يربّي الناس فيصلح أمورهم."], ["أرباباً", "جمع رب بمعنى السيد المعبود."], ["أيأمركم بالكفر", "الاستفهام للإنكار، والكفر هنا الردة عن الإسلام."]], "m": "ما زال السياق في الردّ على أهل الكتاب، وهذه في وفد نصارى نجران خاصة الذين يؤلّهون المسيح ﵇: ليس من شأن إنسان يُنزل الله عليه كتاباً، ويعطيه الفقه في أسراره، ويشرّفه بالنبوة، أن يدعو الناس إلى عبادة نفسه فيقول: كونوا عباداً لي من دون الله؛ هذا ما كان ولن يكون، فكيف تعتقدونه في المسيح؟ ولكن يقول: كونوا ربّانيين تصلحون الناس وتهدونهم إلى ربهم، بتعليمكم الكتاب ودراستكم له. ثم أخبر عن رسوله محمد ﷺ أنه لا يأمر الناس بعبادة غير ربه، ملكاً مكرّماً كان أو نبياً مرسلاً، وأنكر على من نسب ذلك إليه: «أيأمركم بالكفر بعد إذ أنتم مسلمون؟».", "h": ["لم يكن من الممكن لمن آتاه الله الكتاب والحكمة وشرّفه بالنبوة أن يدعو الناس لعبادة نفسه، فضلاً عن عبادة غيره.", "سادات الناس هم الربانيون الذين يربّون الناس بالعلم والحكمة فيصلحونهم ويهدونهم.", "عظماء الناس من يعلّمون الناس الخير ويهدونهم إليه.", "السجود لغير الله كفر؛ لما ورد أن الآية نزلت ردّاً على من أرادوا أن يسجدوا لرسول الله ﷺ."], "k": "«كونوا ربّانيين بما كنتم تعلّمون الكتاب»… ما الخير الذي تعلّمته وأستطيع أن أعلّمه لغيري هذا الأسبوع؟"}, {"lbl": "الآيات ٨١ – ٨٣", "q": "وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيۡتُكُم مِّن كِتَٰبٖ وَحِكۡمَةٖ ثُمَّ جَآءَكُمۡ رَسُولٞ مُّصَدِّقٞ لِّمَا مَعَكُمۡ لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ قَالَ ءَأَقۡرَرۡتُمۡ وَأَخَذۡتُمۡ عَلَىٰ ذَٰلِكُمۡ إِصۡرِيۖ قَالُوٓاْ أَقۡرَرۡنَاۚ قَالَ فَٱشۡهَدُواْ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّـٰهِدِينَ ﴿٨١﴾ فَمَن تَوَلَّىٰ بَعۡدَ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ﴿٨٢﴾ أَفَغَيۡرَ دِينِ ٱللَّهِ يَبۡغُونَ وَلَهُۥٓ أَسۡلَمَ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَإِلَيۡهِ يُرۡجَعُونَ ﴿٨٣﴾", "w": [["الميثاق", "العهد المؤكد باليمين."], ["لما آتيتكم", "مهما آتيتكم."], ["أأقررتم", "الهمزة للاستفهام التقريري، وأقررتم: اعترفتم."], ["إصري", "عهدي وميثاقي."], ["فمن تولّى", "رجع عما اعترف به وأقرّ."], ["أفغير دين الله يبغون", "الاستفهام للإنكار، ويبغون: يطلبون."], ["وله أسلم", "انقاد وخضع لمجاري أقدار الله وأحكامه."]], "m": "ما زال السياق في الردّ على نصارى نجران: اذكر لهم يا رسولنا ما أخذ الله على النبيين وأممهم من الميثاق: أنه مهما آتاهم من كتاب وحكمة ثم جاءهم رسول مصدّق لما معهم ليؤمنُنّ به ولينصرُنّه، فأقرّوا واعترفوا، واستشهدهم فشهدوا، وشهد الله معهم. ثم أكّد أن من أعرض عن هذا الميثاق فأولئك هم الفاسقون. وقد نقضه اليهود والنصارى إذ لم يؤمنوا بمحمد ﷺ ولم ينصروه، فكانوا الفاسقين المستوجبين لعذاب الله. ثم وبّخهم: أفغير دين الله، وهو الإسلام، يطلبون، وقد انقاد له من في السماوات والأرض طائعين أو مكرهين، وإليه يُرجعون فيحاسبهم ويجزيهم؟", "h": ["بيان سنة الله في الأنبياء السابقين، وهي أن يؤمن بعضهم ببعض وينصر بعضهم بعضاً.", "كفر أهل الكتاب وفسقهم بنقضهم الميثاق، وإعراضهم عن الإسلام، وكفرهم بالنبي محمد ﷺ وقد أُخذ عليهم الميثاق بالإيمان به.", "بيان عظم شأن العهود والمواثيق عند الله.", "الإنكار على من يُعرض عن دين الله الإسلام، مع أن الكون كله خاضع منقاد لأمر الله."], "k": "الكون كله أسلم لله طوعاً أو كرهاً… فهل أسلم له باختياري قبل أن أُجبَر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 51;
insert into public.tdb_cards(topic, i, body) select 51, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧٥ – ٧٧", "q": "۞وَمِنۡ أَهۡلِ ٱلۡكِتَٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارٖ يُؤَدِّهِۦٓ إِلَيۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِينَارٖ لَّا يُؤَدِّهِۦٓ إِلَيۡكَ إِلَّا مَا دُمۡتَ عَلَيۡهِ قَآئِمٗاۗ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَيۡسَ عَلَيۡنَا فِي ٱلۡأُمِّيِّـۧنَ سَبِيلٞ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ ﴿٧٥﴾ بَلَىٰۚ مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ ﴿٧٦﴾ إِنَّ ٱلَّذِينَ يَشۡتَرُونَ بِعَهۡدِ ٱللَّهِ وَأَيۡمَٰنِهِمۡ ثَمَنٗا قَلِيلًا أُوْلَـٰٓئِكَ لَا خَلَٰقَ لَهُمۡ فِي ٱلۡأٓخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيۡهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿٧٧﴾", "w": [["إن تأمنه", "إن تجعله أميناً على شيء تضعه عنده."], ["بقنطار", "وزن معروف، والمراد هنا من الذهب."], ["إلا ما دمت عليه قائماً", "إلا إن لازمته تطالبه به ليل نهار."], ["الأميّين", "العرب المشركين."], ["ليس علينا في الأميين سبيل", "لا يؤاخذنا الله إن أكلنا أموالهم لأنهم مشركون."], ["بلى", "ليس الأمر كما يقولون، بل عليهم الإثم والمؤاخذة."], ["لا خلاق لهم", "لا حظّ ولا نصيب لهم في خيرات الآخرة ونعيم الجنان."], ["ولا يزكّيهم", "لا يطهّرهم من ذنوبهم ولا يكفّرها عنهم."]], "m": "ما زال السياق في هتك أستار أهل الكتاب وبيان صفاتهم الذميمة: فمنهم من إن ائتمنته على مال كثير أدّاه إليك كاملاً، ومنهم من إن ائتمنته على دينار خانك فيه وأنكره، فلا يؤدّيه إلا بملازمتك له ومطالبتك. وعلّة ذلك قولهم: لا حرج علينا في أكل أموال العرب لأنهم مشركون، فكذّبهم الله: «ويقولون على الله الكذب وهم يعلمون»، يكذبون ليسوّغوا خيانتهم. ثم قال: «بلى»، ليس الأمر كما يدّعون بل عليهم الإثم والمؤاخذة، وإنما لا إثم على من أوفى بعهد الله فآمن برسوله واتقى الشرك والمعاصي، فإن الله يحب المتقين. ثم توعّد بأشد العقوبات الذين يعاهدون ويخونون ويحلفون كاذبين من أجل حطام الدنيا: أولئك لا نصيب لهم في الآخرة، ولا يكلّمهم الله تشريفاً لهم، ولا ينظر إليهم يوم القيامة، ولا يزكّيهم، ولهم عذاب أليم.", "h": ["لا يُؤتمن اليهود ولا يُوثق بهم لما عُرفوا به من الخيانة.", "من كذب على الله أحرى به أن يكذب على الناس.", "بيان اعتقاد اليهود أن أموال غيرهم وأعراضهم مباحة لهم، لأنهم المؤمنون في نظرهم وغيرهم الكفار.", "عظم ذنب من يخون عهده من أجل المال، وكذا من يحلف كاذباً لأجل المال."], "k": "هل أنا أمين في القليل كما في الكثير، حتى في دينار لا يراه أحد؟"}, {"lbl": "الآية ٧٨", "q": "وَإِنَّ مِنۡهُمۡ لَفَرِيقٗا يَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَٰبِ لِتَحۡسَبُوهُ مِنَ ٱلۡكِتَٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَٰبِ وَيَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِۖ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ ﴿٧٨﴾", "w": [["وإن منهم لفريقاً", "طائفة من اليهود المعاصرين للنبي ﷺ بالمدينة."], ["يلوون ألسنتهم", "يحرّفون ألسنتهم بالكلام كأنهم يقرؤون الكتاب."], ["وما هو من الكتاب", "وليس هو من الكتاب."], ["ويقولون على الله الكذب", "يكذبون على الله لأغراض مادية."]], "m": "ما زال السياق في اليهود وبيان فضائحهم: أخبر تعالى أن طائفة منهم يحرّفون نطقهم بالكلام تمويهاً على السامعين، كأنهم يقرؤون ما أنزل الله في التوراة، وليس هو من الكتاب في شيء، بل هو الكذب البحت، ويقولون: هو من عند الله، وما هو من عند الله، ويقولون على الله الكذب وهم يعلمون، للحفاظ على الحطام الخسيس والرئاسة الكاذبة.", "h": ["بيان مكر اليهود وتضليلهم للناس وخداعهم باسم الدين والعلم.", "جرأة اليهود على الكذب على الناس وعلى الله مع علمهم بأنهم يكذبون، وهو أشدّ قبحاً وأعظم ظلماً.", "تحذير المسلم من سلوك اليهود في التضليل والقول على الله والرسول لأجل الأغراض الدنيوية الفاسدة."], "k": "قبل أن أنسب كلاماً لله أو لرسوله ﷺ… هل أتثبّت من صحته؟"}, {"lbl": "الآيتان ٧٩ – ٨٠", "q": "مَا كَانَ لِبَشَرٍ أَن يُؤۡتِيَهُ ٱللَّهُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُواْ عِبَادٗا لِّي مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُواْ رَبَّـٰنِيِّـۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ ٱلۡكِتَٰبَ وَبِمَا كُنتُمۡ تَدۡرُسُونَ ﴿٧٩﴾ وَلَا يَأۡمُرَكُمۡ أَن تَتَّخِذُواْ ٱلۡمَلَـٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرۡبَابًاۚ أَيَأۡمُرُكُم بِٱلۡكُفۡرِ بَعۡدَ إِذۡ أَنتُم مُّسۡلِمُونَ ﴿٨٠﴾", "w": [["ما كان لبشر", "لم يكن من شأن الإنسان الذي يؤتيه الله الكتاب والحكم والنبوة."], ["الكتاب والحكم والنبوة", "الكتاب: وحي الله المكتوب، والحكم: الحكمة وهي الفقه في أسرار الشرع، والنبوة: تشريف الله عبده بإنبائه بالغيب وتكليمه بالوحي."], ["ربّانيين", "جمع ربّاني: من يُنسب إلى الرب لكثرة عبادته وغزارة علمه، أو الذي يربّي الناس فيصلح أمورهم."], ["أرباباً", "جمع رب بمعنى السيد المعبود."], ["أيأمركم بالكفر", "الاستفهام للإنكار، والكفر هنا الردة عن الإسلام."]], "m": "ما زال السياق في الردّ على أهل الكتاب، وهذه في وفد نصارى نجران خاصة الذين يؤلّهون المسيح ﵇: ليس من شأن إنسان يُنزل الله عليه كتاباً، ويعطيه الفقه في أسراره، ويشرّفه بالنبوة، أن يدعو الناس إلى عبادة نفسه فيقول: كونوا عباداً لي من دون الله؛ هذا ما كان ولن يكون، فكيف تعتقدونه في المسيح؟ ولكن يقول: كونوا ربّانيين تصلحون الناس وتهدونهم إلى ربهم، بتعليمكم الكتاب ودراستكم له. ثم أخبر عن رسوله محمد ﷺ أنه لا يأمر الناس بعبادة غير ربه، ملكاً مكرّماً كان أو نبياً مرسلاً، وأنكر على من نسب ذلك إليه: «أيأمركم بالكفر بعد إذ أنتم مسلمون؟».", "h": ["لم يكن من الممكن لمن آتاه الله الكتاب والحكمة وشرّفه بالنبوة أن يدعو الناس لعبادة نفسه، فضلاً عن عبادة غيره.", "سادات الناس هم الربانيون الذين يربّون الناس بالعلم والحكمة فيصلحونهم ويهدونهم.", "عظماء الناس من يعلّمون الناس الخير ويهدونهم إليه.", "السجود لغير الله كفر؛ لما ورد أن الآية نزلت ردّاً على من أرادوا أن يسجدوا لرسول الله ﷺ."], "k": "«كونوا ربّانيين بما كنتم تعلّمون الكتاب»… ما الخير الذي تعلّمته وأستطيع أن أعلّمه لغيري هذا الأسبوع؟"}, {"lbl": "الآيات ٨١ – ٨٣", "q": "وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيۡتُكُم مِّن كِتَٰبٖ وَحِكۡمَةٖ ثُمَّ جَآءَكُمۡ رَسُولٞ مُّصَدِّقٞ لِّمَا مَعَكُمۡ لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ قَالَ ءَأَقۡرَرۡتُمۡ وَأَخَذۡتُمۡ عَلَىٰ ذَٰلِكُمۡ إِصۡرِيۖ قَالُوٓاْ أَقۡرَرۡنَاۚ قَالَ فَٱشۡهَدُواْ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّـٰهِدِينَ ﴿٨١﴾ فَمَن تَوَلَّىٰ بَعۡدَ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ﴿٨٢﴾ أَفَغَيۡرَ دِينِ ٱللَّهِ يَبۡغُونَ وَلَهُۥٓ أَسۡلَمَ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَإِلَيۡهِ يُرۡجَعُونَ ﴿٨٣﴾", "w": [["الميثاق", "العهد المؤكد باليمين."], ["لما آتيتكم", "مهما آتيتكم."], ["أأقررتم", "الهمزة للاستفهام التقريري، وأقررتم: اعترفتم."], ["إصري", "عهدي وميثاقي."], ["فمن تولّى", "رجع عما اعترف به وأقرّ."], ["أفغير دين الله يبغون", "الاستفهام للإنكار، ويبغون: يطلبون."], ["وله أسلم", "انقاد وخضع لمجاري أقدار الله وأحكامه."]], "m": "ما زال السياق في الردّ على نصارى نجران: اذكر لهم يا رسولنا ما أخذ الله على النبيين وأممهم من الميثاق: أنه مهما آتاهم من كتاب وحكمة ثم جاءهم رسول مصدّق لما معهم ليؤمنُنّ به ولينصرُنّه، فأقرّوا واعترفوا، واستشهدهم فشهدوا، وشهد الله معهم. ثم أكّد أن من أعرض عن هذا الميثاق فأولئك هم الفاسقون. وقد نقضه اليهود والنصارى إذ لم يؤمنوا بمحمد ﷺ ولم ينصروه، فكانوا الفاسقين المستوجبين لعذاب الله. ثم وبّخهم: أفغير دين الله، وهو الإسلام، يطلبون، وقد انقاد له من في السماوات والأرض طائعين أو مكرهين، وإليه يُرجعون فيحاسبهم ويجزيهم؟", "h": ["بيان سنة الله في الأنبياء السابقين، وهي أن يؤمن بعضهم ببعض وينصر بعضهم بعضاً.", "كفر أهل الكتاب وفسقهم بنقضهم الميثاق، وإعراضهم عن الإسلام، وكفرهم بالنبي محمد ﷺ وقد أُخذ عليهم الميثاق بالإيمان به.", "بيان عظم شأن العهود والمواثيق عند الله.", "الإنكار على من يُعرض عن دين الله الإسلام، مع أن الكون كله خاضع منقاد لأمر الله."], "k": "الكون كله أسلم لله طوعاً أو كرهاً… فهل أسلم له باختياري قبل أن أُجبَر؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (52, 3, 84, 92, 'سورة آل عمران ٨٤ – ٩٢', 'الإيمان بالرسل جميعاً، والتوبة، ولن تنالوا البر', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 52) = $j$[{"lbl": "الآيتان ٨٤ – ٨٥", "q": "قُلۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيۡنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ﴿٨٤﴾ وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ ﴿٨٥﴾", "w": [["الأسباط", "جمع سِبط وهو الحفيد، والمراد هنا أولاد يعقوب ﵇ الاثنا عشر، والأسباط في اليهود كالقبائل في العرب."], ["يبتغِ", "يطلب ويريد ديناً غير الإسلام."], ["الخاسرين", "الهالكين بالخلود في النار، الذين خسروا كل شيء حتى أنفسهم."]], "m": "ما زال السياق في حِجاج أهل الكتاب: بعد أن وبّخهم: «أفغير دين الله يبغون؟»، فإن قالوا: نعم، فقل أنت يا رسولنا: آمنا بالله وما أُنزل علينا، وما أُنزل على إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط، وما أوتي موسى من التوراة وعيسى من الإنجيل، وما أوتي النبيون من ربهم، لا نفرّق بين أحد منهم، فلا نؤمن ببعض ونكفر ببعض كحالكم يا معشر اليهود والنصارى، ونحن له مسلمون منقادون لا نعبده بغير ما شرع ولا نعبد معه سواه. ثم قرّر أن كل دين غير الإسلام باطل، وأن من يطلب ديناً غيره فلن يُقبل منه، وهو في الآخرة من الخاسرين الذين يخسرون أنفسهم وأهليهم يوم القيامة.", "h": ["لا يصح إيمان عبد يؤمن ببعض الرسل ويكفر ببعض، ولا من يؤمن ببعض ما أنزل الله ويكفر ببعض.", "الإسلام هو الانقياد والخضوع لله، وهو يتنافى مع التخيير بين رسل الله ووحيه إليهم.", "بطلان سائر الأديان سوى دين الإسلام وملة محمد ﷺ."], "k": "«لا نفرّق بين أحد منهم»… هل أعرف عن الأنبياء غير نبينا ﷺ ما يكفي لأحبّهم وأقتدي بهم؟"}, {"lbl": "الآيات ٨٦ – ٨٩", "q": "كَيۡفَ يَهۡدِي ٱللَّهُ قَوۡمٗا كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ وَشَهِدُوٓاْ أَنَّ ٱلرَّسُولَ حَقّٞ وَجَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٨٦﴾ أُوْلَـٰٓئِكَ جَزَآؤُهُمۡ أَنَّ عَلَيۡهِمۡ لَعۡنَةَ ٱللَّهِ وَٱلۡمَلَـٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ ﴿٨٧﴾ خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ ﴿٨٨﴾ إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿٨٩﴾", "w": [["كيف يهدي الله قوماً", "الاستفهام للاستبعاد، والهداية: الخروج من الضلال."], ["البيّنات", "الحجج من معجزات الرسل وآيات القرآن المبيّنة للحق."], ["الظالمين", "المتجاوزين الحد في الظلم حتى أصبح وصفاً لازماً لهم."], ["لعنة الله", "طرد الله لهم من كل خير، ولعنة الملائكة والناس: دعاؤهم عليهم بذلك."], ["ولا هم يُنظرون", "ولا يُمهلون."], ["وأصلحوا", "أصلحوا ما أفسدوه من أنفسهم ومن غيرهم."]], "m": "ما زال السياق في أهل الكتاب، وإن تناول غيرهم ممن ارتد عن الإسلام ثم عاد إليه فحسُن إسلامه: «كيف يهدي الله قوماً كفروا بعد إيمانهم» وشهدوا أن الرسول حق وجاءتهم البينات؟ والله على سنّته في خلقه لا يهدي من أسرف في الظلم حتى صار طبعاً له، فهدايته مستبعدة للغاية وإن لم تكن مستحيلة. ثم توعّدهم: أولئك جزاؤهم أن عليهم لعنة الله والملائكة والناس أجمعين، خالدين في اللعنة الموجبة للنار، لا يخفّف عنهم العذاب ولا يُمهلون. ثم لما لم تكن توبتهم مستحيلة، ولأن الله يحب توبة عباده ويقبلها، فتح باب رحمته: «إلا الذين تابوا من بعد ذلك وأصلحوا فإن الله غفور رحيم»، فكان كالوعد منه بأن يغفر لهم ويرحمهم.", "h": ["التوغل في الشر والفساد أو الظلم والكفر قد يمنع العبد من التوبة؛ ولذا وجب على العبد إذا أذنب أن يتوب فوراً، ولا يواصل مصرّاً خشية أن يُحال بينه وبين التوبة.", "التوبة مقبولة متى قامت على أسسها واستوفت شروطها: الإقلاع عن الذنب فوراً، والندم على ارتكابه، والاستغفار، والعزم على عدم العودة، وإصلاح ما أفسده مما يمكن إصلاحه."], "k": "ذنب أؤجّل التوبة منه «حتى أستعد»… ماذا لو حيل بيني وبين التوبة؟"}, {"lbl": "الآيتان ٩٠ – ٩١", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّن تُقۡبَلَ تَوۡبَتُهُمۡ وَأُوْلَـٰٓئِكَ هُمُ ٱلضَّآلُّونَ ﴿٩٠﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٞ فَلَن يُقۡبَلَ مِنۡ أَحَدِهِم مِّلۡءُ ٱلۡأَرۡضِ ذَهَبٗا وَلَوِ ٱفۡتَدَىٰ بِهِۦٓۗ أُوْلَـٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ وَمَا لَهُم مِّن نَّـٰصِرِينَ ﴿٩١﴾", "w": [["كفروا", "جحدوا الله وكذّبوا رسوله وما جاء به."], ["بعد إيمانهم", "ارتدّوا عن الإيمان إلى الكفر."], ["الضالّون", "المخطئون طريق الهدى."], ["ملء الأرض", "ما يملؤها من الذهب."], ["ولو افتدى به", "ولو قدّمه فداءً لنفسه من النار ما قُبل منه."]], "m": "ما زال السياق في أهل الكتاب، وهو هنا في اليهود خاصة: كفروا بعيسى ﵇ والإنجيل بعد إيمانهم بموسى ﵇ والتوراة، ثم ازدادوا كفراً بمحمد ﷺ والقرآن، فلن تُقبل توبتهم إلا إذا آمنوا بمحمد ﷺ والقرآن، وهم مصرّون على الكفر بهما، فكيف تُقبل توبتهم؟ وأولئك هم الضالّون البالغون أبعد الحدود في الضلال. ثم قرّر مصيرهم: إن الذين كفروا وماتوا وهم كفار فلن يُقبل من أحدهم ملء الأرض ذهباً ولو افتدى به يوم القيامة، على سبيل الفرض والتقدير، فإنه يوم لا ينفع فيه مال ولا بنون إلا من أتى الله بقلب سليم من الشرك والشك وسائر أمراض القلوب.", "h": ["سنة الله فيمن توغّل في الكفر أو الظلم أو الفسق وبلغ حداً بعيداً أنه لا يتوب.", "لا فدية تُقبل يوم القيامة من أحد، ولا فداء لأحد فيه."], "k": "ملء الأرض ذهباً لا يُقبل هناك… فما الذي يُقبل؟ قلبٌ سليم؛ فكيف حال قلبي اليوم؟"}, {"lbl": "الآية ٩٢", "q": "لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ ﴿٩٢﴾", "w": [["لن تنالوا", "لن تحصلوا عليه وتظفروا به."], ["البرّ", "كلمة جامعة لكل خير، والمراد هنا ثوابه وهو الجنة."], ["تنفقوا", "تتصدقوا."], ["مما تحبّون", "من المال الذي تحبونه لأنفسكم، وهو أفضل أموالكم عندكم."]], "m": "يخبر الله عباده المؤمنين الراغبين في برّه، أن ينجيهم من النار ويدخلهم الجنة، بأنهم لن يظفروا بمطلوبهم حتى ينفقوا من أطيب أموالهم وأنفسها وأحبّها إليهم، ثم طمأنهم بأن ما ينفقونه من قليل أو كثير، نفيس أو خسيس، هو به عليم وسيجزيهم به. وبهذا حبّب إليهم الإنفاق ورغّبهم فيه؛ فجاء أبو طلحة رضي الله عنه فقال: يا رسول الله، إن أحب أموالي إليّ بيرحاء، حديقة له، فاجعلها حيث أراك الله، فقال ﷺ: مال رابح، اجعلها في أقربائك، فجعلها في أقربائه حسان بن ثابت وأُبيّ بن كعب رضي الله عنهم.", "h": ["البرّ، وهو فعل الخير، يهدي إلى الجنة.", "لن يبلغ العبد برّ الله وما عنده من نعيم الآخرة حتى ينفق من أحب أمواله إليه.", "لا يضيع المعروف عند الله قلّ أو كثر، ما دام أُريد به وجهه."], "k": "ما أحبّ شيء عندي؟ وهل أستطيع أن أنفق منه، ولو قليلاً، لله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 52;
insert into public.tdb_cards(topic, i, body) select 52, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٨٤ – ٨٥", "q": "قُلۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيۡنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ﴿٨٤﴾ وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ ﴿٨٥﴾", "w": [["الأسباط", "جمع سِبط وهو الحفيد، والمراد هنا أولاد يعقوب ﵇ الاثنا عشر، والأسباط في اليهود كالقبائل في العرب."], ["يبتغِ", "يطلب ويريد ديناً غير الإسلام."], ["الخاسرين", "الهالكين بالخلود في النار، الذين خسروا كل شيء حتى أنفسهم."]], "m": "ما زال السياق في حِجاج أهل الكتاب: بعد أن وبّخهم: «أفغير دين الله يبغون؟»، فإن قالوا: نعم، فقل أنت يا رسولنا: آمنا بالله وما أُنزل علينا، وما أُنزل على إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط، وما أوتي موسى من التوراة وعيسى من الإنجيل، وما أوتي النبيون من ربهم، لا نفرّق بين أحد منهم، فلا نؤمن ببعض ونكفر ببعض كحالكم يا معشر اليهود والنصارى، ونحن له مسلمون منقادون لا نعبده بغير ما شرع ولا نعبد معه سواه. ثم قرّر أن كل دين غير الإسلام باطل، وأن من يطلب ديناً غيره فلن يُقبل منه، وهو في الآخرة من الخاسرين الذين يخسرون أنفسهم وأهليهم يوم القيامة.", "h": ["لا يصح إيمان عبد يؤمن ببعض الرسل ويكفر ببعض، ولا من يؤمن ببعض ما أنزل الله ويكفر ببعض.", "الإسلام هو الانقياد والخضوع لله، وهو يتنافى مع التخيير بين رسل الله ووحيه إليهم.", "بطلان سائر الأديان سوى دين الإسلام وملة محمد ﷺ."], "k": "«لا نفرّق بين أحد منهم»… هل أعرف عن الأنبياء غير نبينا ﷺ ما يكفي لأحبّهم وأقتدي بهم؟"}, {"lbl": "الآيات ٨٦ – ٨٩", "q": "كَيۡفَ يَهۡدِي ٱللَّهُ قَوۡمٗا كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ وَشَهِدُوٓاْ أَنَّ ٱلرَّسُولَ حَقّٞ وَجَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿٨٦﴾ أُوْلَـٰٓئِكَ جَزَآؤُهُمۡ أَنَّ عَلَيۡهِمۡ لَعۡنَةَ ٱللَّهِ وَٱلۡمَلَـٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ ﴿٨٧﴾ خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ ﴿٨٨﴾ إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿٨٩﴾", "w": [["كيف يهدي الله قوماً", "الاستفهام للاستبعاد، والهداية: الخروج من الضلال."], ["البيّنات", "الحجج من معجزات الرسل وآيات القرآن المبيّنة للحق."], ["الظالمين", "المتجاوزين الحد في الظلم حتى أصبح وصفاً لازماً لهم."], ["لعنة الله", "طرد الله لهم من كل خير، ولعنة الملائكة والناس: دعاؤهم عليهم بذلك."], ["ولا هم يُنظرون", "ولا يُمهلون."], ["وأصلحوا", "أصلحوا ما أفسدوه من أنفسهم ومن غيرهم."]], "m": "ما زال السياق في أهل الكتاب، وإن تناول غيرهم ممن ارتد عن الإسلام ثم عاد إليه فحسُن إسلامه: «كيف يهدي الله قوماً كفروا بعد إيمانهم» وشهدوا أن الرسول حق وجاءتهم البينات؟ والله على سنّته في خلقه لا يهدي من أسرف في الظلم حتى صار طبعاً له، فهدايته مستبعدة للغاية وإن لم تكن مستحيلة. ثم توعّدهم: أولئك جزاؤهم أن عليهم لعنة الله والملائكة والناس أجمعين، خالدين في اللعنة الموجبة للنار، لا يخفّف عنهم العذاب ولا يُمهلون. ثم لما لم تكن توبتهم مستحيلة، ولأن الله يحب توبة عباده ويقبلها، فتح باب رحمته: «إلا الذين تابوا من بعد ذلك وأصلحوا فإن الله غفور رحيم»، فكان كالوعد منه بأن يغفر لهم ويرحمهم.", "h": ["التوغل في الشر والفساد أو الظلم والكفر قد يمنع العبد من التوبة؛ ولذا وجب على العبد إذا أذنب أن يتوب فوراً، ولا يواصل مصرّاً خشية أن يُحال بينه وبين التوبة.", "التوبة مقبولة متى قامت على أسسها واستوفت شروطها: الإقلاع عن الذنب فوراً، والندم على ارتكابه، والاستغفار، والعزم على عدم العودة، وإصلاح ما أفسده مما يمكن إصلاحه."], "k": "ذنب أؤجّل التوبة منه «حتى أستعد»… ماذا لو حيل بيني وبين التوبة؟"}, {"lbl": "الآيتان ٩٠ – ٩١", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّن تُقۡبَلَ تَوۡبَتُهُمۡ وَأُوْلَـٰٓئِكَ هُمُ ٱلضَّآلُّونَ ﴿٩٠﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٞ فَلَن يُقۡبَلَ مِنۡ أَحَدِهِم مِّلۡءُ ٱلۡأَرۡضِ ذَهَبٗا وَلَوِ ٱفۡتَدَىٰ بِهِۦٓۗ أُوْلَـٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ وَمَا لَهُم مِّن نَّـٰصِرِينَ ﴿٩١﴾", "w": [["كفروا", "جحدوا الله وكذّبوا رسوله وما جاء به."], ["بعد إيمانهم", "ارتدّوا عن الإيمان إلى الكفر."], ["الضالّون", "المخطئون طريق الهدى."], ["ملء الأرض", "ما يملؤها من الذهب."], ["ولو افتدى به", "ولو قدّمه فداءً لنفسه من النار ما قُبل منه."]], "m": "ما زال السياق في أهل الكتاب، وهو هنا في اليهود خاصة: كفروا بعيسى ﵇ والإنجيل بعد إيمانهم بموسى ﵇ والتوراة، ثم ازدادوا كفراً بمحمد ﷺ والقرآن، فلن تُقبل توبتهم إلا إذا آمنوا بمحمد ﷺ والقرآن، وهم مصرّون على الكفر بهما، فكيف تُقبل توبتهم؟ وأولئك هم الضالّون البالغون أبعد الحدود في الضلال. ثم قرّر مصيرهم: إن الذين كفروا وماتوا وهم كفار فلن يُقبل من أحدهم ملء الأرض ذهباً ولو افتدى به يوم القيامة، على سبيل الفرض والتقدير، فإنه يوم لا ينفع فيه مال ولا بنون إلا من أتى الله بقلب سليم من الشرك والشك وسائر أمراض القلوب.", "h": ["سنة الله فيمن توغّل في الكفر أو الظلم أو الفسق وبلغ حداً بعيداً أنه لا يتوب.", "لا فدية تُقبل يوم القيامة من أحد، ولا فداء لأحد فيه."], "k": "ملء الأرض ذهباً لا يُقبل هناك… فما الذي يُقبل؟ قلبٌ سليم؛ فكيف حال قلبي اليوم؟"}, {"lbl": "الآية ٩٢", "q": "لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ ﴿٩٢﴾", "w": [["لن تنالوا", "لن تحصلوا عليه وتظفروا به."], ["البرّ", "كلمة جامعة لكل خير، والمراد هنا ثوابه وهو الجنة."], ["تنفقوا", "تتصدقوا."], ["مما تحبّون", "من المال الذي تحبونه لأنفسكم، وهو أفضل أموالكم عندكم."]], "m": "يخبر الله عباده المؤمنين الراغبين في برّه، أن ينجيهم من النار ويدخلهم الجنة، بأنهم لن يظفروا بمطلوبهم حتى ينفقوا من أطيب أموالهم وأنفسها وأحبّها إليهم، ثم طمأنهم بأن ما ينفقونه من قليل أو كثير، نفيس أو خسيس، هو به عليم وسيجزيهم به. وبهذا حبّب إليهم الإنفاق ورغّبهم فيه؛ فجاء أبو طلحة رضي الله عنه فقال: يا رسول الله، إن أحب أموالي إليّ بيرحاء، حديقة له، فاجعلها حيث أراك الله، فقال ﷺ: مال رابح، اجعلها في أقربائك، فجعلها في أقربائه حسان بن ثابت وأُبيّ بن كعب رضي الله عنهم.", "h": ["البرّ، وهو فعل الخير، يهدي إلى الجنة.", "لن يبلغ العبد برّ الله وما عنده من نعيم الآخرة حتى ينفق من أحب أمواله إليه.", "لا يضيع المعروف عند الله قلّ أو كثر، ما دام أُريد به وجهه."], "k": "ما أحبّ شيء عندي؟ وهل أستطيع أن أنفق منه، ولو قليلاً، لله؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;